import { Reducer } from 'redux';
import { ConnectionActionType } from './connectionTypes';
import { PeerActionType } from '../peer/peerTypes';
import { Card, Character, CharacterCategory, Deck, Decks, GameState, PlayerAbility, PlayerAttack, PlayerChoice, PlayerEndTurn, PlayerEvent, PlayerMove, UserDetails, ConnectionState, ChoiceType, Player, LogEntry, PlayerActionType, Piece, Trigger, VersionMismatch } from '../../helpers/common';
import { PeerConnection } from '../../helpers/peer';
import RawDecks from '../../helpers/decks.json';
import { shuffle } from 'fast-shuffle';
import { attackModifierFor, attackRangeFor, CustomCardFunction, hasMachineGun, hasRobe, hasSword, usesSingleDieAttack } from '../../helpers/cardAction';
import { abilityLog, applyAbility, handleAbility, isHost } from './abilityActions';
import { resolveVictory } from './victoryResolver';

const drawDecks = [2, 3, 6, 8];
const discardableDecks = [Decks.green, Decks.black, Decks.white] as const;
type DiscardableDeck = (typeof discardableDecks)[number];

function isDiscardableDeck(deck: string): deck is DiscardableDeck {
    return (discardableDecks as readonly string[]).includes(deck);
}

function getDiscardablePile(state: ConnectionState, drawDeck: string) {
    if (!isDiscardableDeck(drawDeck)) return undefined;
    const deck = state.gameState.lobby.decks[drawDeck];
    const discard = state.gameState.lobby.discard[drawDeck];
    return deck && discard ? { deck, discard } : undefined;
}

function pendingDeckCard(state: ConnectionState, card: Card): Card | undefined {
    const pile = getDiscardablePile(state, card.drawDeck);
    return pile?.deck.cards.find(entry => entry.name === card.name);
}

function discardPendingCard(state: ConnectionState, card: Card) {
    const pendingCard = pendingDeckCard(state, card);
    if (!pendingCard) return undefined;
    const pile = getDiscardablePile(state, pendingCard.drawDeck);
    if (!pile) return undefined;
    return {
        card: pendingCard,
        decks: { ...state.gameState.lobby.decks, [pendingCard.drawDeck]: { cards: pile.deck.cards.filter(entry => entry !== pendingCard) } },
        discard: { ...state.gameState.lobby.discard, [pendingCard.drawDeck]: { cards: [pendingCard, ...pile.discard.cards] } }
    };
}

function resolveRevealedDrawCard(state: ConnectionState, card: Card, playerList: Player[]): ConnectionState {
    const pending = discardPendingCard(state, card);
    if (!pending) return {
        ...state,
        gameState: { ...state.gameState, lobby: { ...state.gameState.lobby, playerList } }
    };
    const result = CustomCardFunction({ ...state.gameState, lobby: { ...state.gameState.lobby, playerList } }, pending.card);
    const resolvedPlayers = result?.playersTargeted
        ? playerList.map(player => result.playersTargeted!.find(target => target.user.id === player.user.id) ?? player)
        : playerList;
    return {
        ...state,
        gameState: {
            ...state.gameState,
            lobby: {
                ...state.gameState.lobby,
                playerList: resolvedPlayers,
                decks: pending.decks,
                discard: pending.discard,
                gameLog: [...state.gameState.lobby.gameLog, ...(result?.logEntry ?? [])]
            }
        }
    };
}

export const initialState: ConnectionState = {
    id: undefined,
    peerId: undefined,
    loading: false,
    playerEvents: [],
    gameState: {
        started: false,
        gameEnded: false,
        hostId: undefined,
        currentPlayer: '',
        nextPlayer: '',
        botThinkTimeMs: 750,
        completedTurns: 0,
        lobby: {
            playerList: [],
            gameLog: [],
            neutral: RawDecks.characters.neutral,
            shadow: RawDecks.characters.shadow,
            hunter: RawDecks.characters.hunter,
            decks: { green: { cards: [] }, white: { cards: [] }, black: { cards: [] }, areas: { cards: [] } },
            discard: { green: { cards: [] }, white: { cards: [] }, black: { cards: [] } }
        }
    }
}

const blankCharacter: Character = { maxHealth: 0, category: 1, name: '' };
export const blankPiece: Piece = { character: { ...blankCharacter }, damage: 0, items: [], revealed: false, position: -1, protected: false, dead: false, abilityUsed: false, abilityBlocked: false, moved: false, attacked: false };

function addBotHostilities(gameState: GameState, event: PlayerAttack) {
    let hostilities = gameState.botHostilities;
    event.targets.forEach(target => {
        const targetPlayer = gameState.lobby.playerList.find(player => player.user.id === target.id);
        if (!targetPlayer?.user.isBot || targetPlayer.user.id === event.playerId) return;
        const attackers = hostilities?.[targetPlayer.user.id] ?? [];
        if (attackers.includes(event.playerId)) return;
        hostilities = {
            ...hostilities,
            [targetPlayer.user.id]: [...attackers, event.playerId]
        };
    });
    return hostilities;
}

function rememberBotFactionKnowledge(gameState: GameState, card: Card, targetId?: string, assumedCategory?: CharacterCategory) {
    if (card.drawDeck !== Decks.green || !card.name.startsWith("Hermit's ") || !targetId) {
        return gameState.botFactionKnowledge;
    }
    const observer = gameState.lobby.playerList.find(player => player.user.id === gameState.currentPlayer);
    const target = gameState.lobby.playerList.find(player => player.user.id === targetId);
    if (!observer?.user.isBot || !target?.user.isBot || observer.user.id === target.user.id) {
        return gameState.botFactionKnowledge;
    }
    const faction = assumedCategory ?? target.piece.character.category;
    if (gameState.botFactionKnowledge?.[observer.user.id]?.[target.user.id] === faction) {
        return gameState.botFactionKnowledge;
    }
    return {
        ...gameState.botFactionKnowledge,
        [observer.user.id]: {
            ...gameState.botFactionKnowledge?.[observer.user.id],
            [target.user.id]: faction
        }
    };
}

function validAttackRoll(roll: number[], singleDie: boolean): boolean {
    const validDie = (value: number, sides: number) => Number.isInteger(value) && value >= 1 && value <= sides;
    return singleDie
        ? roll.length === 1 && validDie(roll[0]!, 4)
        : roll.length === 2 && validDie(roll[0]!, 6) && validDie(roll[1]!, 4);
}

function validAttackTargets(gameState: GameState, attacker: Player, event: PlayerAttack, pendingCounterattack: GameState['pendingCounterattack']): boolean {
    if (event.targets.length === 0) return false;
    const targetIds = event.targets.map(target => target.id);
    const uniqueTargetIds = new Set(targetIds);
    const resolvedTargets = targetIds.map(id => gameState.lobby.playerList.find(player => player.user.id === id));
    if (uniqueTargetIds.size !== targetIds.length
        || resolvedTargets.some(target => !target || target.piece.dead || target.user.id === attacker.user.id)) {
        return false;
    }
    if (pendingCounterattack) {
        return event.playerId === pendingCounterattack.responderId
            && targetIds.length === 1 && targetIds[0] === pendingCounterattack.attackerId;
    }
    if (!attacker.piece.moved || attacker.piece.attacked) return false;

    const legalTargetIds = new Set(attackRangeFor(gameState, attacker).map(player => player.user.id));
    if (hasMachineGun(attacker)) {
        return targetIds.length === legalTargetIds.size && targetIds.every(id => legalTargetIds.has(id));
    }
    return targetIds.length === 1 && legalTargetIds.has(targetIds[0]!);
}

export const ConnectionReducer: Reducer<ConnectionState> = (state = initialState, action) => {
    // A refresh is the recovery path for a version mismatch. Do not restore a
    // stale prompt from persisted state before the new build can communicate.
    if (action.type === 'persist/REHYDRATE') {
        return { ...state, versionMismatch: undefined };
    }
    switch (action.type) {
        case ConnectionActionType.CONNECTION_VERSION_MISMATCH:
            return { ...state, versionMismatch: action.payload as VersionMismatch };
        case PeerActionType.PEER_SESSION_START:
            return { ...state, peerId: action.payload as string };
        case PeerActionType.PEER_SESSION_STOP:
            return { ...state, peerId: undefined };
        case ConnectionActionType.CONNECTION_ID_CHANGE:
            return { ...state, id: action.payload as string };
        case ConnectionActionType.CONNECTION_GAMESTATE_SHUFFLE:
            if (action.payload as string | undefined) {
                const drawDeck = action.payload as string;
                const pile = getDiscardablePile(state, drawDeck);
                if (!pile) return state;

                return {
                    ...state, gameState: {
                        ...state.gameState,
                        lobby: {
                            ...state.gameState.lobby,
                            decks: {
                                ...state.gameState.lobby.decks,
                                [drawDeck]: {
                                    cards: shuffle([...pile.deck.cards, ...pile.discard.cards])
                                }
                            },
                            discard: {
                                ...state.gameState.lobby.discard,
                                [drawDeck]: { cards: [] }
                            }
                        }
                    }
                };
            }
            else {
                return {
                    ...state, gameState: {
                        ...state.gameState,
                        lobby: {
                            ...state.gameState.lobby,
                            decks: {
                                green: { cards: shuffle(RawDecks.green as Card[]) },
                                white: { cards: shuffle(RawDecks.white as Card[]) },
                                black: { cards: shuffle(RawDecks.black as Card[]) },
                                areas: { cards: shuffle(RawDecks.areas as Card[]) }
                            },
                            discard: {
                                green: { cards: [] },
                                white: { cards: [] },
                                black: { cards: [] }
                            }
                        }
                    }
                };
            }
        case ConnectionActionType.CONNECTION_CONNECT_LOADING:
            return { ...state, loading: action.payload as boolean };
        case ConnectionActionType.CONNECTION_GAMESTATE_ABILITY:
            if (state.gameState.disconnectedPlayer) return state;
            return handleAbility(state, action.payload as PlayerAbility);
        case ConnectionActionType.CONNECTION_GAMESTATE_UPDATE:
            return { ...state, gameState: action.payload as GameState };
        case ConnectionActionType.CONNECTION_GAMESTATE_RECOVERED: {
            const payload = action.payload as { gameState: GameState, gameId: string };
            if (payload.gameState.gameId !== payload.gameId || !payload.gameState.started || payload.gameState.gameEnded) return state;
            return { ...state, gameState: payload.gameState, recoveredGameId: payload.gameId };
        }
        case ConnectionActionType.CONNECTION_GAMESTATE_ATTACK: {
            const event = action.payload as PlayerAttack;
            if (state.gameState.gameEnded || state.gameState.disconnectedPlayer) {
                return state;
            }
            const currentPlayer = state.gameState.lobby.playerList.find(x => x.user.id === state.gameState.currentPlayer);
            if (!currentPlayer) return state;
            const pendingCounterattack = state.gameState.pendingCounterattack;
            const singleDieAttack = usesSingleDieAttack(currentPlayer);
            const rolledDamage = singleDieAttack
                ? event.damageRoll[0]!
                : Math.abs(event.damageRoll[0]! - event.damageRoll[1]!);
            const totalDamage = Math.max(0, rolledDamage + attackModifierFor(currentPlayer));

            if (!isHost(state)) {
                PeerConnection.sendAttack(event, state.id!);
                return state;
            }
            if (event.playerId !== currentPlayer.user.id
                || currentPlayer.piece.dead
                || !validAttackRoll(event.damageRoll, singleDieAttack)
                || !validAttackTargets(state.gameState, currentPlayer, event, pendingCounterattack)) {
                return state;
            }
            const botHostilities = addBotHostilities(state.gameState, event);
            if (totalDamage === 0) {
                //attack missed

                const playerList = state.gameState.lobby.playerList.map(x => {
                    if (x.user.id === state.gameState.currentPlayer) {
                        return { ...x, piece: { ...x.piece, attacked: true } };
                    }

                    return x;
                });
                const nextPlayer = nextLivingPlayer(playerList, state.gameState.nextPlayer, true);
                const followingPlayer = nextLivingPlayer(playerList, nextPlayer, false);

                return {
                    ...state, gameState: {
                        ...state.gameState,
                        currentPlayer: nextPlayer,
                        nextPlayer: followingPlayer,
                        completedTurns: (state.gameState.completedTurns ?? 0) + 1,
                        pendingCounterattack: undefined,
                        botHostilities,
                        lobby: {
                            ...state.gameState.lobby,
                            playerList: startTurn(playerList, nextPlayer),
                            gameLog: [...state.gameState.lobby.gameLog,
                            {
                                source: 'Attack',
                                text: `missed their attack on ${event.targets.map(x => x.userName).join(', ')}.`,
                                userName: currentPlayer.user.userName,
                                info: ''
                            }]
                        }
                    }
                }
            }
            else {
                //apply damage to targets
                const items: Card[] = [];
                const defeatedPlayers: Player[] = [];
                let playerList = state.gameState.lobby.playerList.map(x => {
                    if (event.targets.map(y => y.id).includes(x.user.id)) {
                        if (x.piece.protected)
                            return x;

                        const damage = x.piece.damage + totalDamage - (hasRobe(x) ? 1 : 0);
                        const dead = damage >= x.piece.character.maxHealth;
                        if (dead) {
                            items.push(...x.piece.items);
                            defeatedPlayers.push(x);
                            PeerConnection.sendDeath({ character: x.piece.character, playerId: x.user.id, actionType: PlayerActionType.playerDeath });
                        }

                        return {
                            ...x,
                            piece: {
                                ...x.piece,
                                damage,
                                revealed: dead ? dead : x.piece.revealed,
                                position: 0,
                                dead,
                                items: []
                            }
                        };
                    }
                    else if (x.user.id === state.gameState.currentPlayer) {
                        return { ...x, piece: { ...x.piece, attacked: true } };
                    }

                    return x;
                });

                const attackedPlayerIds = new Set(event.targets.map(target => target.id));
                const targets = playerList.filter(x => event.targets.map(y => y.id).includes(x.user.id)).map(x => x.piece);
                const attackAbilityPlayers = currentPlayer.piece.character.ability?.name === 'suckBlood' && totalDamage > 0
                    ? [currentPlayer]
                    : [];
                playerList = triggerAutomaticAbilities(state.gameState, playerList, attackAbilityPlayers, currentPlayer.user.id);
                const triggeredPlayers = getAutomaticAbilityPlayers(playerList, currentPlayer.user.id, targets);
                playerList = triggerAutomaticAbilities(state.gameState, playerList, triggeredPlayers, currentPlayer.user.id);
                const victory = resolveVictory(state, playerList, targets);
                const counterattackResponder = !pendingCounterattack && !victory.gameEnded
                    ? playerList.find(player => attackedPlayerIds.has(player.user.id)
                        && !player.piece.dead
                        && !player.piece.abilityUsed
                        && !player.piece.abilityBlocked
                        && !player.piece.character.ability?.automatic
                        && player.piece.character.ability?.triggerOn === Trigger.attacked)
                    : undefined;
                const nextPlayer = nextLivingPlayer(playerList, state.gameState.nextPlayer, true);
                const followingPlayer = nextLivingPlayer(playerList, nextPlayer, false);
                const activePlayer = counterattackResponder?.user.id ?? nextPlayer;

                return {
                    ...state, gameState: {
                        ...state.gameState,
                        currentPlayer: activePlayer,
                        nextPlayer: counterattackResponder ? nextPlayer : followingPlayer,
                        completedTurns: (state.gameState.completedTurns ?? 0) + (counterattackResponder && !pendingCounterattack ? 0 : 1),
                        pendingCounterattack: counterattackResponder
                            ? { responderId: counterattackResponder.user.id, attackerId: currentPlayer.user.id }
                            : undefined,
                        pendingLoot: items.length > 0 ? { killerId: currentPlayer.user.id, items } : undefined,
                        gameEnded: victory.gameEnded,
                        winner: victory.winner,
                        victors: victory.victors,
                        botHostilities,
                        lobby: {
                            ...state.gameState.lobby,
                            playerList: counterattackResponder ? playerList : startTurn(playerList, activePlayer),
                            discard: state.gameState.lobby.discard,
                            gameLog: [...state.gameState.lobby.gameLog,
                            ...attackAbilityPlayers.map(player => abilityLog(player)),
                            ...triggeredPlayers.map(player => abilityLog(player)),
                            {
                                source: 'Attack',
                                text: `attacked ${event.targets.map(x => x.userName).join(', ')} for ${totalDamage} damage.`,
                                userName: currentPlayer.user.userName,
                                info: ''
                            },
                            ...defeatedPlayers.map(player => ({
                                source: 'Death',
                                text: `died.`,
                                userName: player.user.userName,
                                info: ''
                            }))]
                        }
                    }
                };
            }
        }
        case ConnectionActionType.CONNECTION_GAMESTATE_MOVE:
            if (state.gameState.disconnectedPlayer) return state;
            return handleMove(action.payload as PlayerMove, state);
        case ConnectionActionType.CONNECTION_GAMESTATE_END_TURN:
            if (state.gameState.disconnectedPlayer) return state;
            return handleEndTurn(action.payload as PlayerEndTurn, state);
        case ConnectionActionType.CONNECTION_GAMESTATE_CHOICE: {
            const event = action.payload as PlayerChoice;
            if (state.gameState.disconnectedPlayer) return state;

            if (!isHost(state) && event.result) {
                //We're not the host, the host needs our choice
                PeerConnection.sendChoice(event, state.id!);
                return state;
            }
            else if (event.result) {
                //We're the host and we have a result to the choice
                const eventPlayerEntry = state.gameState.lobby.playerList.find(x => x.user.id === event.playerId);
                const targetPlayerEntry = state.gameState.lobby.playerList.find(x => x.user.id === event.choice.target);
                if (!eventPlayerEntry || !targetPlayerEntry) return state;
                const eventPlayer = eventPlayerEntry.user.userName;
                let targetPlayer = targetPlayerEntry.user.userName;

                switch (event.choice.type) {
                    case ChoiceType.equipment: {
                        if (event.result === 'skip') return skipCardChoice(state, event, eventPlayer);
                        const [ownerId, itemName] = event.result.split(',');
                        const owner = state.gameState.lobby.playerList.find(player => player.user.id === ownerId);
                        const item = owner?.piece.items.find(candidate => candidate.name === itemName);
                        if (!owner || !item) return state;
                        const isAltar = event.choice.card.name === 'Erstwhile Altar';
                        const isBanana = event.choice.card.name === 'Banana Peel';
                        if ((isAltar && owner.user.id === event.playerId)
                            || (!isAltar && owner.user.id !== event.choice.target)) return state;
                        const pending = discardPendingCard(state, event.choice.card);
                        if (!isAltar && !pending) return state;
                        const playerList = state.gameState.lobby.playerList.map(x => {
                            if (!isBanana && x.user.id === event.playerId) {
                                return { ...x, piece: { ...x.piece, items: [...x.piece.items, item] } };
                            }
                            else if (x.user.id === ownerId) {
                                return { ...x, piece: { ...x.piece, items: x.piece.items.filter(candidate => candidate !== item) } };
                            }

                            return x;
                        });

                        return {
                            ...state,
                            gameState: {
                                ...state.gameState,
                                lobby: {
                                    ...state.gameState.lobby,
                                    playerList,
                                    ...(pending ? { decks: pending.decks, discard: pending.discard } : {}),
                                    gameLog: [...state.gameState.lobby.gameLog, {
                                        source: isAltar ? 'Erstwhile Altar' : 'Card',
                                        text: isBanana ? `discarded ${item.name}.`
                                            : isAltar ? `stole ${item.name} from ${owner.user.userName}.`
                                                : `took ${item.name} from ${owner.user.userName}.`,
                                        userName: eventPlayer,
                                        info: isAltar ? 'areas/Erstwhile Altar' : `${event.choice.card.drawDeck}/${event.choice.card.name}`
                                    }]
                                }
                            }
                        };
                    }
                    case ChoiceType.hermitGreed: {
                        const target = state.gameState.lobby.playerList.find(player => player.user.id === event.choice.target);
                        const recipient = state.gameState.lobby.playerList.find(player => player.user.id === event.playerId);
                        if (!target || !recipient || target.piece.dead || target.piece.character.category === CharacterCategory.hunter) return state;
                        const pending = discardPendingCard(state, event.choice.card);
                        if (!pending) return state;

                        if (event.result === 'damage') {
                            const playerList = state.gameState.lobby.playerList.map(player => player.user.id === target.user.id
                                ? { ...player, piece: { ...player.piece, damage: player.piece.damage + 1 } }
                                : player);
                            return {
                                ...state,
                                gameState: {
                                    ...state.gameState,
                                    lobby: {
                                        ...state.gameState.lobby,
                                        playerList,
                                        ...(pending ? { decks: pending.decks, discard: pending.discard } : {}),
                                        gameLog: [...state.gameState.lobby.gameLog, {
                                            source: 'Card',
                                            text: `gave Hermit Card to ${target.user.userName} and ${target.user.userName} chose to take 1 damage.`,
                                            userName: eventPlayer,
                                            info: 'card_backs/green'
                                        }]
                                    }
                                }
                            };
                        }

                        const [ownerId, itemName] = event.result.split(',');
                        if (ownerId !== target.user.id || !itemName) return state;
                        const item = target.piece.items.find(candidate => candidate.name === itemName);
                        if (!item) return state;
                        const playerList = state.gameState.lobby.playerList.map(player => {
                            if (player.user.id === recipient.user.id) {
                                return { ...player, piece: { ...player.piece, items: [...player.piece.items, item] } };
                            }
                            if (player.user.id === target.user.id) {
                                return { ...player, piece: { ...player.piece, items: player.piece.items.filter(candidate => candidate !== item) } };
                            }
                            return player;
                        });
                        return {
                            ...state,
                            gameState: {
                                ...state.gameState,
                                lobby: {
                                    ...state.gameState.lobby,
                                    playerList,
                                    ...(pending ? { decks: pending.decks, discard: pending.discard } : {}),
                                    gameLog: [...state.gameState.lobby.gameLog, {
                                        source: 'Card',
                                        text: `gave Hermit Card to ${target.user.userName} and ${target.user.userName} gave ${item.name} to ${recipient.user.userName}.`,
                                        userName: eventPlayer,
                                        info: `${item.drawDeck}/${item.name}`
                                    }]
                                }
                            }
                        };
                    }
                    case ChoiceType.hermitFaction: {
                        const target = state.gameState.lobby.playerList.find(player => player.user.id === event.choice.target);
                        const category = event.result === 'shadow' ? CharacterCategory.shadow
                            : event.result === 'hunter' ? CharacterCategory.hunter
                                : event.result === 'neutral' ? CharacterCategory.neutral : undefined;
                        if (!target || target.piece.character.name !== 'Unknown' || category === undefined) return state;
                        return handleCardLogic(event.choice.card, state, state.gameState.lobby.playerList, {
                            source: 'Card',
                            text: `resolved ${event.choice.card.name} for ${target.user.userName}.`,
                            userName: eventPlayer,
                            info: 'card_backs/green'
                        }, target.user.id, undefined, category);
                    }
                    case ChoiceType.move:
                        //value is new move
                        const moveRoll = JSON.parse(event.result);
                        return handleMove({ moveRoll, playerId: state.gameState.currentPlayer, actionType: PlayerActionType.playerChoice }, state);
                    case ChoiceType.rerollMovement: {
                        const reroll = JSON.parse(event.result) as number[];
                        if (reroll.length !== 2 || reroll.some(die => !Number.isInteger(die) || die < 1)) return state;
                        return handleMove({ moveRoll: reroll, playerId: event.playerId, actionType: PlayerActionType.playerMove }, state);
                    }
                    case ChoiceType.teleport: {
                        const originalRoll = event.choice.value ? JSON.parse(event.choice.value) as number[] : undefined;
                        if (!originalRoll || originalRoll.length !== 2) return state;
                        return handleMove(
                            { moveRoll: originalRoll, playerId: event.playerId, actionType: PlayerActionType.playerMove },
                            state,
                            event.result === 'normal' ? undefined : event.result,
                            true
                        );
                    }
                    case ChoiceType.area: {
                        const selectedArea = state.gameState.lobby.decks[Decks.areas].cards
                            .find(card => card.name === event.result);
                        if (!selectedArea || !event.choice.value) return state;

                        const originalRoll = JSON.parse(event.choice.value) as number[];
                        if (originalRoll.length !== 2 || originalRoll[0] + originalRoll[1] !== 7) return state;
                        return handleMove({ moveRoll: originalRoll, playerId: event.playerId, actionType: PlayerActionType.playerMove }, state, selectedArea.name);
                    }
                    case ChoiceType.reveal:
                        //yes no
                        if (!['yes', 'no'].includes(event.result) || event.playerId !== event.choice.target) return state;
                        if (event.result === 'yes') {
                            const playerList = state.gameState.lobby.playerList.map(x => {
                                if (x.user.id === event.playerId) {
                                    return { ...x, piece: { ...x.piece, revealed: true } };
                                }

                                return x;
                            });

                            const revealedState: ConnectionState = {
                                ...state,
                                gameState: {
                                    ...state.gameState,
                                    lobby: {
                                        ...state.gameState.lobby,
                                        playerList,
                                        gameLog: [...state.gameState.lobby.gameLog,
                                        {
                                            source: 'Choice',
                                            text: `revealed themselves as ${playerList.filter(x => x.user.userName === targetPlayer).map(x => x.piece.character.name)[0]}.`,
                                            userName: eventPlayer,
                                            info: ''
                                        }]
                                    }
                                }
                            };
                            return pendingDeckCard(state, event.choice.card)
                                ? resolveRevealedDrawCard(revealedState, event.choice.card, playerList)
                                : revealedState;
                        }
                        if (pendingDeckCard(state, event.choice.card)) {
                            return resolveRevealedDrawCard(state, event.choice.card, state.gameState.lobby.playerList);
                        }
                        break;
                    case ChoiceType.showCard:
                        // The receiving player has dismissed the private character reveal.
                        // The Hermit card already logged its public outcome.
                        return state;
                    case ChoiceType.target:
                        //user.id
                        if (event.result === 'skip') return skipCardChoice(state, event, eventPlayer);
                        const selectedTarget = state.gameState.lobby.playerList.find(player => player.user.id === event.result);
                        if (!selectedTarget || selectedTarget.piece.dead) return state;
                        if (event.choice.card.name?.startsWith("Hermit's ") && selectedTarget.user.id === event.playerId) return state;
                        targetPlayer = selectedTarget.user.userName;

                        if (event.choice.card.name === 'Weird Woods') {
                            const followUpChoice: PlayerChoice = {
                                playerId: event.playerId,
                                actionType: PlayerActionType.playerChoice,
                                choice: { card: event.choice.card, type: ChoiceType.weirdWoods, target: event.result }
                            };
                            const choosingPlayer = state.gameState.lobby.playerList.find(player => player.user.id === event.playerId);
                            if (isHost(state) && (event.playerId === state.peerId || choosingPlayer?.user.isBot)) {
                                PeerConnection.choiceCallback(followUpChoice);
                            }
                            else {
                                PeerConnection.sendChoice(followUpChoice, event.playerId);
                            }
                            return state;
                        }
                        else {
                            return handleCardLogic(event.choice.card, state, state.gameState.lobby.playerList,
                                {
                                    source: 'Choice',
                                    text: `targeted ${targetPlayer} for ${event.choice.card.name}.`,
                                    userName: eventPlayer,
                                    info: `${event.choice.card.drawDeck}/${event.choice.card.name}`
                                }, event.result)
                        }
                    case ChoiceType.weirdWoods: {
                        const target = state.gameState.lobby.playerList.find(player => player.user.id === event.choice.target);
                        if (!target || target.piece.dead || !['damage', 'heal'].includes(event.result)) return state;
                        const damage = event.result === 'damage'
                            ? target.piece.damage + 2
                            : Math.max(0, target.piece.damage - 1);
                        const actionText = event.result === 'damage'
                            ? `dealt 2 damage to ${target.user.userName === state.gameState.currentPlayer ? 'themselves' : target.user.userName}.`
                            : `healed ${target.user.userName === state.gameState.currentPlayer ? 'themselves' : target.user.userName} for 1 damage.`;
                        return {
                            ...state,
                            gameState: {
                                ...state.gameState,
                                lobby: {
                                    ...state.gameState.lobby,
                                    playerList: state.gameState.lobby.playerList.map(player => player.user.id === target.user.id
                                        ? { ...player, piece: { ...player.piece, damage } }
                                        : player),
                                    gameLog: [...state.gameState.lobby.gameLog, { source: 'Weird Woods', text: actionText, userName: eventPlayer, info: 'areas/Weird Woods' }]
                                }
                            }
                        };
                    }
                    case ChoiceType.draw:
                        //deck
                        const roll = event.choice.value ? JSON.parse(event.choice.value) as number[] : undefined;
                        return handleDraw(event.result, state, state.gameState.lobby.playerList, eventPlayer,
                            {
                                source: event.choice.card.drawDeck === Decks.areas ? event.choice.card.name : 'Choice',
                                text: event.choice.card.drawDeck === Decks.areas
                                    ? `rolled ${roll?.join(' + ') ?? 'for movement'} and moved to the ${event.choice.card.name}, then chose to draw from the ${event.result} deck.`
                                    : `chose to draw from the ${event.result} deck.`,
                                userName: eventPlayer,
                                info: event.choice.card.drawDeck === Decks.areas ? `areas/${event.choice.card.name}` : `card_backs/${event.result}`
                            }
                        );
                    default:
                        break;
                }

                return state;
            }
            else {
                //We're the host but haven't made our decision yet
                //or
                //We're not the host, the host sent us a choice to make a decision on
                PeerConnection.choiceCallback(event);
                return state;
            }
        }
        case ConnectionActionType.CONNECTION_ADD_PLAYER_LOBBY: {
            const { rejoinGameId, ...user } = action.payload as UserDetails;
            const existingPlayer = state.gameState.lobby.playerList.find(player => player.user.id === user.id);
            const canReclaimReplacementBot = existingPlayer?.user.isBot && existingPlayer.user.replacedPlayerName !== undefined;
            if (rejoinGameId !== undefined && (!state.gameState.started || state.gameState.gameEnded
                || state.gameState.gameId !== rejoinGameId || !existingPlayer || (existingPlayer.user.isBot && !canReclaimReplacementBot))) return state;
            // A reconnect must not reset a live player's character, items, or
            // board position. Only a replacement bot can be reclaimed.
            if (existingPlayer?.user.isBot && !(rejoinGameId !== undefined && canReclaimReplacementBot)) return state;
            const reconnectingPlayer = existingPlayer
                ? { ...existingPlayer, user: { ...existingPlayer.user, ...user, isBot: false, replacedPlayerName: undefined } }
                : { user, piece: { ...blankPiece } };
            return {
                ...state, gameState: {
                    ...state.gameState,
                    disconnectedPlayer: state.gameState.disconnectedPlayer?.playerId === user.id ? undefined : state.gameState.disconnectedPlayer,
                    lobby: {
                        ...state.gameState.lobby,
                        playerList: existingPlayer
                            ? state.gameState.lobby.playerList.map(player => player.user.id === user.id ? reconnectingPlayer : player)
                            : [...state.gameState.lobby.playerList, reconnectingPlayer]
                    }
                }
            };
        }
        case ConnectionActionType.CONNECTION_REMOVE_PLAYER_LOBBY: {
            const connectionId = action.payload as string;
            if (state.id === connectionId) {
                return {
                    ...state,
                    id: undefined,
                    gameState: initialState.gameState
                };
            }
            else {
                return {
                    ...state, gameState: {
                        ...state.gameState, lobby: {
                            ...state.gameState.lobby,
                            playerList: [...state.gameState.lobby.playerList].filter(e => e.user.id !== connectionId)
                        }
                    }
                };
            }
        }
        case ConnectionActionType.CONNECTION_PLAYER_DISCONNECTED: {
            const playerId = action.payload as string;
            const player = state.gameState.lobby.playerList.find(entry => entry.user.id === playerId);
            if (!player) return state;
            if (!state.gameState.started) {
                if (state.id === playerId) {
                    return { ...state, id: undefined, gameState: initialState.gameState };
                }
                return {
                    ...state,
                    gameState: {
                        ...state.gameState,
                        lobby: {
                            ...state.gameState.lobby,
                            playerList: state.gameState.lobby.playerList.filter(entry => entry.user.id !== playerId)
                        }
                    }
                };
            }
            if (state.gameState.disconnectedPlayer) return state;
            return {
                ...state,
                gameState: {
                    ...state.gameState,
                    disconnectedPlayer: {
                        playerId,
                        playerName: player.user.userName,
                        isHost: playerId === state.gameState.hostId
                    }
                }
            };
        }
        case ConnectionActionType.CONNECTION_RESOLVE_DISCONNECTED_PLAYER: {
            const { playerId, resolution } = action.payload as { playerId: string, resolution: 'replace' | 'end' };
            const disconnected = state.gameState.disconnectedPlayer;
            if (state.peerId !== state.gameState.hostId || disconnected?.playerId !== playerId) return state;
            if (resolution === 'end') {
                return {
                    ...state,
                    gameState: {
                        ...state.gameState,
                        gameEnded: true,
                        winner: undefined,
                        victors: [],
                        endedByDisconnect: true,
                        disconnectedPlayer: undefined,
                        pendingCounterattack: undefined,
                        pendingLoot: undefined
                    }
                };
            }
            return {
                ...state,
                gameState: {
                    ...state.gameState,
                    disconnectedPlayer: undefined,
                    lobby: {
                        ...state.gameState.lobby,
                        playerList: state.gameState.lobby.playerList.map(player => player.user.id === playerId
                            ? {
                                ...player,
                                user: {
                                    ...player.user,
                                    userName: `Bot (${disconnected.playerName})`,
                                    isBot: true,
                                    replacedPlayerName: disconnected.playerName
                                }
                            }
                            : player)
                    }
                }
            };
        }
        case ConnectionActionType.CONNECTION_END_HOSTED_GAME:
            if (state.peerId !== state.gameState.hostId) return state;
            return {
                ...state,
                gameState: {
                    ...state.gameState,
                    gameEnded: true,
                    winner: undefined,
                    victors: [],
                    endedByHost: true,
                    disconnectedPlayer: undefined,
                    pendingCounterattack: undefined,
                    pendingLoot: undefined
                }
            };
        case ConnectionActionType.CONNECTION_CLEAR_EXPIRED_GAME:
            return { ...initialState, peerId: state.peerId };
        case ConnectionActionType.CONNECTION_ASSIGN_CHARACTERS: {
            const characters = charactersForPlayers(state);
            const playerList = state.gameState.lobby.playerList.map((x, i) => {
                return { ...x, piece: { ...x.piece, character: characters[i] } };
            });

            return {
                ...state,
                gameState: {
                    ...state.gameState,
                    lobby: {
                        ...state.gameState.lobby,
                        playerList
                    }
                }
            };
        }
        case ConnectionActionType.CONNECTION_REMOVE_EVENT:
            return { ...state, playerEvents: state.playerEvents.slice(1) }
        case ConnectionActionType.CONNECTION_ADD_EVENT:
            return { ...state, playerEvents: [...state.playerEvents, action.payload as PlayerEvent] }
        default:
            return state;

    }
}

export function nextLivingPlayer(playerList: Player[], playerId: string, includeStart = false): string {
    if (playerList.length === 0) return playerId;
    const start = Math.max(0, playerList.findIndex(player => player.user.id === playerId));
    for (let offset = includeStart ? 0 : 1; offset < playerList.length + (includeStart ? 0 : 1); offset++) {
        const player = playerList[(start + offset) % playerList.length];
        if (!player.piece.dead) return player.user.id;
    }
    return playerId;
}

export function startTurn(playerList: Player[], playerId: string): Player[] {
    return playerList.map(player => player.user.id === playerId && !player.piece.dead
        ? { ...player, piece: { ...player.piece, moved: false, attacked: false, protected: false } }
        : player);
}


function getAutomaticAbilityPlayers(playerList: Player[], attackerId: string, targets: Piece[]): Player[] {
    const deathOccurred = targets.some(target => target.dead);
    return playerList.filter(player => {
        const ability = player.piece.character.ability;
        if (!ability?.automatic || player.piece.abilityUsed || player.piece.abilityBlocked || player.piece.character.automaticAbilityAlwaysActive) {
            return false;
        }
        if (ability.triggerOn === Trigger.death) {
            return deathOccurred && !player.piece.dead;
        }
        if (ability.triggerOn === Trigger.kill) {
            return player.user.id === attackerId && targets.some(target => target.dead && target.character.maxHealth <= 12);
        }
        return false;
    });
}

function triggerAutomaticAbilities(gameState: GameState, playerList: Player[], players: Player[], attackerId: string): Player[] {
    return players.reduce((updated, player) => applyAbility({ ...gameState, lobby: { ...gameState.lobby, playerList: updated } }, player.user.id, attackerId), playerList);
}

export const GetCharacters = (state: ConnectionState) => {
    const drawCharacters = (deck: Character[], count: number) => shuffle([...deck]).slice(0, count);
    const playerCount = state.gameState.lobby.playerList.length;
    switch (playerCount) {
        case 4:
            return [
                ...drawCharacters(state.gameState.lobby.hunter, 2),
                ...drawCharacters(state.gameState.lobby.shadow, 2)
            ];
        case 8:
            return [
                ...drawCharacters(state.gameState.lobby.hunter, 3),
                ...drawCharacters(state.gameState.lobby.shadow, 3),
                ...drawCharacters(state.gameState.lobby.neutral, 2)
            ];
        default:
            return [
                ...drawCharacters(state.gameState.lobby.hunter, 2),
                ...drawCharacters(state.gameState.lobby.shadow, 2),
                ...drawCharacters(state.gameState.lobby.neutral, Math.max(0, playerCount - 4))
            ];
    }
}

export function charactersForPlayers(state: ConnectionState): Character[] {
    const players = state.gameState.lobby.playerList;
    const characters = shuffle(GetCharacters(state));
    const botIneligibleIndex = characters.findIndex(character => character.botEligible === false);
    if (botIneligibleIndex !== -1 && players.every(player => player.user.isBot)) {
        const selected = new Set(characters.map(character => character.name));
        const replacement = state.gameState.lobby.shadow.find(character => character.botEligible !== false && !selected.has(character.name));
        if (replacement) characters[botIneligibleIndex] = replacement;
    }
    const available = [...characters];
    const allocation: Character[] = Array(players.length);

    // Allocate bots first so an ineligible character cannot be left over for a
    // bot that is later in lobby order.
    players.forEach((player, index) => {
        if (!player.user.isBot) return;
        const characterIndex = available.findIndex(character => character.botEligible !== false);
        allocation[index] = available.splice(characterIndex, 1)[0];
    });
    players.forEach((player, index) => {
        if (player.user.isBot) return;
        allocation[index] = available.shift()!;
    });
    return allocation;
}

export function getPositionFromMove(moveRoll: number, areas: Deck) {
    const index = areas.cards.findIndex(card => card.damage === moveRoll || card.heal === moveRoll);
    return index === -1 ? undefined : { card: areas.cards[index], index };
}

function deliverChoice(state: ConnectionState, choice: PlayerChoice, recipientId: string) {
    const recipient = state.gameState.lobby.playerList.find(player => player.user.id === recipientId);
    if (recipientId === state.peerId || recipient?.user.isBot) {
        PeerConnection.choiceCallback(choice);
    }
    else {
        PeerConnection.sendChoice(choice, recipientId);
    }
}

function handleMove(event: PlayerMove, state: ConnectionState, selectedAreaName?: string, skipTeleportChoice = false): ConnectionState {
    const currentPlayer = state.gameState.lobby.playerList.find(player => player.user.id === state.gameState.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead || event.playerId !== currentPlayer.user.id) return state;
    if (!isHost(state)) {
        //if client is not the host, send the decision to the host
        PeerConnection.sendMove(event, state.id!);
        return state;
    }
    else {
        //host executes state mutation for self or client
        const moveResult = event.moveRoll[0] + event.moveRoll[1];
        const areas = state.gameState.lobby.decks[Decks.areas];
        const currentPlayerName = currentPlayer.user.userName;

        if (!skipTeleportChoice && currentPlayer.piece.character.ability?.name === 'teleport'
            && currentPlayer.piece.position >= 0) {
            deliverChoice(state, {
                choice: {
                    card: { name: 'Teleport', drawDeck: Decks.characters },
                    type: ChoiceType.teleport,
                    target: currentPlayer.user.id,
                    value: JSON.stringify(event.moveRoll)
                },
                playerId: currentPlayer.user.id,
                actionType: PlayerActionType.playerChoice
            }, currentPlayer.user.id);
            return state;
        }

        // A seven lets the player choose any named area instead of rolling again.
        if (moveResult === 7 && !selectedAreaName) {
            const choice = {
                choice: { card: { name: 'Choose Destination', drawDeck: Decks.areas }, type: ChoiceType.area, target: state.gameState.currentPlayer, value: JSON.stringify(event.moveRoll) },
                playerId: state.gameState.currentPlayer,
                actionType: PlayerActionType.playerChoice
            };
            deliverChoice(state, choice, currentPlayer.user.id);
            return state;
        }

        const position = selectedAreaName === undefined
            ? getPositionFromMove(moveResult, areas)
            : (() => {
                const index = areas.cards.findIndex(card => card.name === selectedAreaName);
                return index === -1 ? undefined : { card: areas.cards[index], index };
            })();
        if (!position) return state;

        if (position.index === currentPlayer.piece.position) {
            deliverChoice(state, {
                choice: {
                    card: { name: 'Reroll Movement', drawDeck: Decks.areas },
                    type: ChoiceType.rerollMovement,
                    target: currentPlayer.user.id
                },
                playerId: currentPlayer.user.id,
                actionType: PlayerActionType.playerChoice
            }, currentPlayer.user.id);
            return state;
        }

        const moveLog = {
            source: position.card.name,
            text: `rolled ${event.moveRoll.join(' + ')} and moved to the ${position.card.name}.`,
            userName: currentPlayerName,
            info: `areas/${position.card.name}`
        };

        const playerList = state.gameState.lobby.playerList.map(x => {
            if (x.user.id === state.gameState.currentPlayer) {
                return { ...x, piece: { ...x.piece, position: position.index, moved: true } };
            }

            return x;
        });

        if (position.card.name === 'Underworld Gate') {
            const choice = {
                choice: { card: position.card, type: ChoiceType.draw, value: JSON.stringify(event.moveRoll), target: state.gameState.currentPlayer },
                playerId: state.gameState.currentPlayer,
                actionType: PlayerActionType.playerChoice
            };
            deliverChoice(state, choice, state.gameState.currentPlayer);

            return { ...state, gameState: { ...state.gameState, lobby: { ...state.gameState.lobby, playerList } } };;
        }

        if (drawDecks.includes(position.card.damage!)) {
            return handleDraw(position.card.drawDeck, state, playerList, currentPlayerName, moveLog);
        }
        else if (position.card.name === 'Erstwhile Altar') {
            //Erstwhile Altar
            if (state.gameState.lobby.playerList.some(x => x.piece.items.length > 0 && x.user.id !== state.gameState.currentPlayer)) {
                //at least one player other than the current player has an item to steal
                const choice = {
                    choice: { card: position.card, type: ChoiceType.equipment, target: state.gameState.currentPlayer },
                    playerId: state.gameState.currentPlayer,
                    actionType: PlayerActionType.playerChoice
                };
                deliverChoice(state, choice, state.gameState.currentPlayer);

                return { ...state, gameState: { ...state.gameState, lobby: { ...state.gameState.lobby, playerList } } };
            }
            else {
                //no player has items
                return {
                    ...state, gameState: {
                        ...state.gameState,
                        lobby: {
                            ...state.gameState.lobby,
                            playerList,
                            gameLog: [...state.gameState.lobby.gameLog, moveLog, {
                                source: 'Erstwhile Altar',
                                text: 'could not steal any equipment because no other player has equipment.',
                                userName: currentPlayerName,
                                info: 'areas/Erstwhile Altar'
                            }]
                        }
                    }
                };
            }
        }
        else {
            //Weird Woods
            const choice = {
                choice: { card: position.card, type: ChoiceType.target, target: state.gameState.currentPlayer },
                playerId: state.gameState.currentPlayer,
                actionType: PlayerActionType.playerChoice
            };
            deliverChoice(state, choice, state.gameState.currentPlayer);

            return { ...state, gameState: { ...state.gameState, lobby: { ...state.gameState.lobby, playerList } } };
        }
    }
}

function handleEndTurn(event: PlayerEndTurn, state: ConnectionState): ConnectionState {
    if (!isHost(state)) {
        PeerConnection.sendEndTurn(event, state.id!);
        return state;
    }
    const currentPlayer = state.gameState.lobby.playerList.find(player => player.user.id === state.gameState.currentPlayer);
    if (!currentPlayer || state.gameState.gameEnded || state.gameState.pendingCounterattack || state.gameState.pendingLoot
        || event.playerId !== currentPlayer.user.id || currentPlayer.piece.dead || !currentPlayer.piece.moved || currentPlayer.piece.attacked
        || (hasSword(currentPlayer) && attackRangeFor(state.gameState, currentPlayer).length > 0)) {
        return state;
    }
    const playerList = state.gameState.lobby.playerList.map(player => player.user.id === currentPlayer.user.id
        ? { ...player, piece: { ...player.piece, attacked: true } }
        : player);
    const nextPlayer = nextLivingPlayer(playerList, state.gameState.nextPlayer, true);
    return {
        ...state,
        gameState: {
            ...state.gameState,
            currentPlayer: nextPlayer,
            nextPlayer: nextLivingPlayer(playerList, nextPlayer, false),
            completedTurns: (state.gameState.completedTurns ?? 0) + 1,
            lobby: {
                ...state.gameState.lobby,
                playerList: startTurn(playerList, nextPlayer),
                gameLog: [...state.gameState.lobby.gameLog, {
                    source: 'Turn', text: `ended their turn.`, userName: currentPlayer.user.userName, info: ''
                }]
            }
        }
    };
}

/** Resolve an impossible optional card choice without leaving the turn blocked. */
function skipCardChoice(state: ConnectionState, event: PlayerChoice, playerName: string): ConnectionState {
    const card = pendingDeckCard(state, event.choice.card);
    if (!card) return state;
    const pile = getDiscardablePile(state, card.drawDeck);
    if (!pile) return state;
    return {
        ...state,
        gameState: {
            ...state.gameState,
            lobby: {
                ...state.gameState.lobby,
                decks: { ...state.gameState.lobby.decks, [card.drawDeck]: { cards: pile.deck.cards.filter(entry => entry !== card) } },
                discard: { ...state.gameState.lobby.discard, [card.drawDeck]: { cards: [card, ...pile.discard.cards] } },
                gameLog: [...state.gameState.lobby.gameLog, { source: 'Choice', text: `could not use ${card.name}.`, userName: playerName, info: '' }]
            }
        }
    };
}

function handleDraw(drawDeck: string, state: ConnectionState, playerList: Player[], currentPlayer: string, moveLog: LogEntry): ConnectionState {
    const pile = getDiscardablePile(state, drawDeck);
    if (!pile) return state;
    const { deck, discard } = pile;
    const drawPile = deck.cards.length > 0 ? deck.cards : shuffle([...(discard?.cards ?? [])]);
    if (drawPile.length === 0) return state;
    const drawState = deck.cards.length > 0 ? state : {
        ...state,
        gameState: {
            ...state.gameState,
            lobby: {
                ...state.gameState.lobby,
                decks: { ...state.gameState.lobby.decks, [drawDeck]: { cards: drawPile } },
                discard: { ...state.gameState.lobby.discard, [drawDeck]: { cards: [] } }
            }
        }
    };
    const card = drawPile[Math.floor(Math.random() * drawPile.length)];
    if (card.drawDeck !== drawDeck) return state;
    const isPublicDraw = drawDeck === Decks.black || drawDeck === Decks.white;
    const drawLog: LogEntry = {
        source: 'Draw',
        text: isPublicDraw ? `drew ${card.name} from the ${drawDeck} deck.` : `drew a Hermit card.`,
        userName: currentPlayer,
        info: isPublicDraw ? `${drawDeck}/${card.name}` : `card_backs/${drawDeck}`
    };

    if (!card.isItem) {
        //Card is not an item, check if the card has custom logic or choices
        return handleCardLogic(card, drawState, playerList, moveLog, undefined, drawLog);
    }
    else {
        //Card is item, add item to  inventory and return
        const drawPileState = getDiscardablePile(drawState, card.drawDeck);
        if (!drawPileState) return state;
        playerList = playerList.map(x => {
            if (x.user.id === state.gameState.currentPlayer) {
                return { ...x, piece: { ...x.piece, items: [...x.piece.items, card] } };
            }

            return x;
        });

        return {
            ...drawState, gameState: {
                ...drawState.gameState,
                lobby: {
                    ...drawState.gameState.lobby,
                    playerList,
                    gameLog: [...drawState.gameState.lobby.gameLog, moveLog, drawLog],
                    decks: {
                        ...drawState.gameState.lobby.decks,
                        [card.drawDeck]: { cards: drawPileState.deck.cards.filter(entry => entry !== card) }
                    }
                }
            }
        };
    }
}

function handleCardLogic(card: Card, state: ConnectionState, playerList: Player[], moveLog: LogEntry, target?: string, drawLog?: LogEntry, assumedHermitCategory?: CharacterCategory) {
    const pendingCard = pendingDeckCard(state, card);
    if (!pendingCard) return state;
    card = pendingCard;
    const pile = getDiscardablePile(state, card.drawDeck);
    if (!pile) return state;
    const result = CustomCardFunction(state.gameState, card, target, assumedHermitCategory);
    const botFactionKnowledge = rememberBotFactionKnowledge(state.gameState, card, target, assumedHermitCategory);
    if (!result) {
        return {
            ...state, gameState: {
                ...state.gameState,
                botFactionKnowledge,
                lobby: {
                    ...state.gameState.lobby,
                    gameLog: [...state.gameState.lobby.gameLog, moveLog, ...(drawLog ? [drawLog] : [])],
                    decks: { ...state.gameState.lobby.decks, [card.drawDeck]: { cards: pile.deck.cards.filter(entry => entry !== card) } },
                    discard: { ...state.gameState.lobby.discard, [card.drawDeck]: { cards: [card, ...pile.discard.cards] } }
                }
            }
        };
    }

    if (card.isPublic) {
        result.logEntry = result.logEntry ? [...result.logEntry] : [];
    }

    if (result.choice) {
        //If player needs to make a choice return to main loop
        const targetIsBot = state.gameState.lobby.playerList.find(player => player.user.id === result.choice!.target)?.user.isBot;
        if (isHost(state) && (result.choice.target === state.peerId || targetIsBot)) {
            PeerConnection.choiceCallback({
                choice: result.choice,
                playerId: state.gameState.currentPlayer,
                actionType: PlayerActionType.playerChoice
            });
        }
        else {
            PeerConnection.sendChoice({
                choice: result.choice,
                playerId: state.gameState.currentPlayer,
                actionType: PlayerActionType.playerChoice
            }, result.choice.target);
        }

        return {
            ...state, gameState: {
                ...state.gameState,
                botFactionKnowledge,
                lobby: {
                    ...state.gameState.lobby,
                    playerList,
                    gameLog: [...state.gameState.lobby.gameLog, ...(drawLog ? [drawLog] : []), ...result.logEntry!, moveLog]
                }
            }
        };
    }

    //If players were targeted by cards, deal damage
    if (result.playersTargeted) {
        playerList = playerList.map(x => {
            const target = result.playersTargeted!.filter(y => y.user.id === x.user.id);
            if (target.length > 0) {
                return target[0];
            }

            return x;
        });
    }

    //No choices need to be made so we can discard the card and apply the changes
    return {
        ...state, gameState: {
            ...state.gameState,
            nextPlayer: result?.nextPlayer ?? state.gameState.nextPlayer,
            botFactionKnowledge,
            lobby: {
                ...state.gameState.lobby,
                playerList,
                gameLog: result?.logEntry
                    ? [...state.gameState.lobby.gameLog, moveLog, ...(drawLog ? [drawLog] : []), ...result!.logEntry!]
                    : [...state.gameState.lobby.gameLog, moveLog, ...(drawLog ? [drawLog] : [])],
                decks: {
                    ...state.gameState.lobby.decks,
                    [card.drawDeck]: {
                        cards: pile.deck.cards.filter(entry => entry !== card)
                    }
                },
                discard: {
                    ...state.gameState.lobby.discard,
                    [card.drawDeck]: {
                        cards: [card, ...pile.discard.cards]
                    }
                }
            }
        }
    };
}
