import { Middleware } from 'redux';
import { PeerConnection } from '../../helpers/peer';
import { Card, ChoiceType, ConnectionState, Decks, GameState, LogEntry, PlayerActionType, PlayerChoice, PlayerEvent } from '../../helpers/common';
import { ConnectionActionType } from './connectionTypes';
import { addPlayerEvent } from './connectionActions';

interface StateWithConnection {
    connection: ConnectionState
}

type GameAction = { type?: string, payload?: PlayerEvent & Record<string, unknown> };

function publicCardFromDraw(entry: LogEntry): Card | undefined {
    const [drawDeck, ...nameParts] = entry.info.split('/');
    if (![Decks.black, Decks.white].includes(drawDeck as Decks) || nameParts.length === 0) return undefined;
    return { name: nameParts.join('/'), drawDeck: drawDeck as Decks, isPublic: true };
}

/** Build player-facing notifications from the authoritative state transition. */
export function playerEventsForTransition(before: GameState, after: GameState, action: GameAction): PlayerEvent[] {
    const event = action.payload;
    if (!event) return [];

    const logs = after.lobby.gameLog.slice(before.lobby.gameLog.length);
    const choice = event as unknown as PlayerChoice;
    const isPrivateUnknownHermitChoice = action.type === ConnectionActionType.CONNECTION_GAMESTATE_CHOICE
        && choice.choice?.type === ChoiceType.target
        && choice.choice.card.name.startsWith("Hermit's ")
        && after.lobby.playerList.find(player => player.user.id === choice.result)?.piece.character.name === 'Unknown';
    const isPrivateHermitPrediction = action.type === ConnectionActionType.CONNECTION_GAMESTATE_CHOICE
        && choice.choice?.type === ChoiceType.target
        && choice.choice.card.name === "Hermit's Prediction";
    const isPublicCharacterReveal = action.type === ConnectionActionType.CONNECTION_GAMESTATE_CHOICE
        && choice.choice?.type === ChoiceType.reveal && choice.result === 'yes';
    const revealedPlayer = isPublicCharacterReveal
        ? after.lobby.playerList.find(player => player.user.id === choice.playerId)
        : undefined;
    const lastLog = (entries: LogEntry[]) => entries.length > 0 ? entries[entries.length - 1] : undefined;
    const outcome = action.type === ConnectionActionType.CONNECTION_GAMESTATE_ATTACK
        ? lastLog(logs.filter(entry => entry.source === 'Attack'))
        : action.type === ConnectionActionType.CONNECTION_GAMESTATE_CHOICE
            ? lastLog(logs.filter(entry => ['Card', 'Choice', 'Weird Woods', 'Loot'].includes(entry.source)))
            : undefined;
    const actingPlayer = after.lobby.playerList.find(player => player.user.id === event.playerId);
    const isPrivateUnrevealedChoice = action.type === ConnectionActionType.CONNECTION_GAMESTATE_CHOICE
        && !isPublicCharacterReveal
        && !actingPlayer?.piece.revealed
        && !outcome;
    const isPrivateCounterattackDecision = action.type === ConnectionActionType.CONNECTION_GAMESTATE_ABILITY
        && Boolean((event as Record<string, unknown>).skipCounterattack);
    const actionEvent: PlayerEvent | undefined = isPrivateUnknownHermitChoice || isPrivateHermitPrediction || isPrivateUnrevealedChoice || isPrivateCounterattackDecision
        ? undefined : revealedPlayer
        ? {
            playerId: revealedPlayer.user.id,
            actionType: PlayerActionType.playerChoice,
            revealedCard: { ...revealedPlayer.piece.character, drawDeck: Decks.characters } as Card
        }
        : { ...event, message: action.type === ConnectionActionType.CONNECTION_GAMESTATE_ATTACK ? undefined : outcome?.text };
    const attackOutcome: PlayerEvent[] = action.type === ConnectionActionType.CONNECTION_GAMESTATE_ATTACK && outcome
        ? [{
            playerId: event.playerId,
            actionType: PlayerActionType.playerAttack,
            message: outcome.text,
            animateDice: false
        }]
        : [];
    const deathEvents: PlayerEvent[] = after.lobby.playerList
        .filter(player => player.piece.dead && !before.lobby.playerList.find(previous => previous.user.id === player.user.id)?.piece.dead)
        .map(player => ({
            playerId: player.user.id,
            actionType: PlayerActionType.playerDeath,
            message: 'died.',
            animateDice: false
        }));
    const drawEvents = logs
        .filter(entry => entry.source === 'Draw')
        .map(entry => ({
            playerId: event.playerId,
            actionType: PlayerActionType.playerDraw,
            card: publicCardFromDraw(entry),
            message: entry.text
        }));
    return [...(actionEvent ? [actionEvent] : []), ...attackOutcome, ...deathEvents, ...drawEvents];
}

export const gameStateReplicationMiddleware: Middleware<{}, StateWithConnection> = store => next => action => {
    const before = store.getState().connection.gameState;
    const result = next(action);
    const connection = store.getState().connection;

    if (connection.gameState !== before && connection.gameState.hostId === connection.peerId) {
        void PeerConnection.updateAllPlayers(connection);

        const eventTypes = new Set<string>([
            ConnectionActionType.CONNECTION_GAMESTATE_MOVE,
            ConnectionActionType.CONNECTION_GAMESTATE_ATTACK,
            ConnectionActionType.CONNECTION_GAMESTATE_CHOICE,
            ConnectionActionType.CONNECTION_GAMESTATE_ABILITY,
            ConnectionActionType.CONNECTION_GAMESTATE_END_TURN
        ]);
        const candidate = action as GameAction;
        if (candidate.type && eventTypes.has(candidate.type) && candidate.payload) {
            playerEventsForTransition(before, connection.gameState, candidate).forEach(playerEvent => {
                store.dispatch(addPlayerEvent(playerEvent));
                void PeerConnection.sendPlayerEvent(playerEvent);
            });
        }
    }

    return result;
};
