import { Reducer } from 'redux';
import { PeerActionType, PeerState, UserData } from './peerTypes';

export const initialState: PeerState = {
    id: undefined,
    userData: { userName: '', color: '#fff' },
    loading: false,
    started: false
}

export const PeerReducer: Reducer<PeerState> = (state = initialState, action) => {
    switch (action.type) {
        case PeerActionType.PEER_SESSION_START:
            return { ...state, id: action.payload as string, started: true };
        case PeerActionType.PEER_SESSION_STOP:
            return { ...initialState };
        case PeerActionType.PEER_LOADING:
            return { ...state, loading: action.payload as boolean };
        case PeerActionType.PEER_SET_USER_DATA:
            return { ...state, userData: action.payload as UserData };
        default:
            return state;
    }
}