import { ConnectionActionType } from './connectionTypes';
import { Dispatch } from 'redux';
import { PeerConnection } from '../../helpers/peer';
import { DataType, GameState, PlayerAbility, PlayerAttack, PlayerChoice, PlayerEndTurn, PlayerEvent, PlayerMove, UserDetails, VersionMismatch } from '../../helpers/common';

export const changeConnectionInput = (id: string | undefined) => ({
    type: ConnectionActionType.CONNECTION_ID_CHANGE, payload: id
});

export const setLoading = (loading: boolean) => ({
    type: ConnectionActionType.CONNECTION_CONNECT_LOADING, payload: loading
});

export const updateGameState = (newState: GameState) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_UPDATE, payload: newState
});

export const recoverGameState = (newState: GameState, gameId: string) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_RECOVERED,
    payload: { gameState: newState, gameId }
});

export const reportVersionMismatch = (mismatch: VersionMismatch) => ({
    type: ConnectionActionType.CONNECTION_VERSION_MISMATCH,
    payload: mismatch
});

export const attack = (event: PlayerAttack) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_ATTACK, payload: event
});

export const move = (event: PlayerMove) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_MOVE, payload: event
});

export const endTurn = (event: PlayerEndTurn) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_END_TURN, payload: event
});

export const choice = (event: PlayerChoice) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_CHOICE, payload: event
});

export const useAbility = (event: PlayerAbility) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_ABILITY, payload: event
});

export const playerDisconnected = (playerId: string) => ({
    type: ConnectionActionType.CONNECTION_PLAYER_DISCONNECTED, payload: playerId
});

export const replaceDisconnectedPlayer = (playerId: string) => ({
    type: ConnectionActionType.CONNECTION_RESOLVE_DISCONNECTED_PLAYER,
    payload: { playerId, resolution: 'replace' as const }
});

export const endGameAfterDisconnect = (playerId: string) => ({
    type: ConnectionActionType.CONNECTION_RESOLVE_DISCONNECTED_PLAYER,
    payload: { playerId, resolution: 'end' as const }
});

export const endHostedGame = () => ({
    type: ConnectionActionType.CONNECTION_END_HOSTED_GAME
});

export const clearExpiredGame = () => ({
    type: ConnectionActionType.CONNECTION_CLEAR_EXPIRED_GAME
});

export const shuffleDecks = (deck?: string) => ({
    type: ConnectionActionType.CONNECTION_GAMESTATE_SHUFFLE, payload: deck
});

export const removePlayerFromLobby = (playerId: string) => ({
    type: ConnectionActionType.CONNECTION_REMOVE_PLAYER_LOBBY, payload: playerId
});

export const addPlayerToLobby = (player: UserDetails) => ({
    type: ConnectionActionType.CONNECTION_ADD_PLAYER_LOBBY, payload: player
});

export const assignCharacters = () => ({
    type: ConnectionActionType.CONNECTION_ASSIGN_CHARACTERS
});

export const removeEvent = () => ({
    type: ConnectionActionType.CONNECTION_REMOVE_EVENT
});

export const addPlayerEvent = (event: PlayerEvent) => ({
    type: ConnectionActionType.CONNECTION_ADD_EVENT, payload: event
});

export const connectPeer: (id: string, user: UserDetails, rejoinGameId?: string) => (dispatch: Dispatch) => Promise<void>
    = (id: string, user: UserDetails, rejoinGameId?: string) => (async (dispatch) => {
        dispatch(setLoading(true));
        try {
            await PeerConnection.connectPeer(id);

            PeerConnection.onConnectionDisconnected(id, () => {
                dispatch(playerDisconnected(id));
            });

            PeerConnection.onConnectionReceiveData(id, (data) => {
                //Receive data from host
                switch (data.dataType) {
                    case DataType.VersionMismatch: {
                        const details = JSON.parse(data.body) as { receivedVersion?: string };
                        dispatch(reportVersionMismatch({ peerId: id, remoteVersion: data.appVersion ?? details.receivedVersion }));
                        dispatch(setLoading(false));
                        return;
                    }
                    case DataType.GameState:
                        const gameState = JSON.parse(data.body) as GameState;
                        const validRecovery = rejoinGameId === undefined || (gameState.gameId === rejoinGameId
                            && gameState.started && !gameState.gameEnded
                            && gameState.lobby.playerList.some(player => player.user.id === user.id));
                        if (!validRecovery) {
                            dispatch(clearExpiredGame());
                            dispatch(setLoading(false));
                            return;
                        }
                        dispatch(rejoinGameId === undefined ? updateGameState(gameState) : recoverGameState(gameState, rejoinGameId));
                        dispatch(setLoading(false));
                        return;
                    case DataType.GameRecoveryRejected:
                        if (rejoinGameId !== undefined) dispatch(clearExpiredGame());
                        dispatch(setLoading(false));
                        return;
                    case DataType.PlayerChoice:
                        dispatch(choice(JSON.parse(data.body)));
                        return;
                    case DataType.PlayerAbility:
                        dispatch(useAbility(JSON.parse(data.body)));
                        return;
                    case DataType.PlayerEndTurn:
                        dispatch(endTurn(JSON.parse(data.body)));
                        return;
                    case DataType.PlayerEvent:
                        dispatch(addPlayerEvent(JSON.parse(data.body)));
                        return;
                }
            });

            await PeerConnection.sendConnection(id, {
                dataType: DataType.UserDetails,
                body: JSON.stringify(rejoinGameId === undefined ? user : { ...user, rejoinGameId })
            }).catch(e => console.log(e));
        } catch (e) {
            if (rejoinGameId !== undefined) dispatch(clearExpiredGame());
            dispatch(setLoading(false));
            console.log(e);
        }
    });
