import { CharacterCategory, Decks, GameState, Piece, Player } from './common';

function killThirteen(_state: GameState, _player: Player, targets: Piece[] = []): boolean {
    return targets.some(target => target.character.maxHealth >= 13 && target.dead);
}

function onAltar(state: GameState, player: Player): boolean {
    return state.lobby.decks[Decks.areas].cards[player.piece.position]?.name === 'Erstwhile Altar';
}

function dieFirst(state: GameState, player: Player): boolean {
    return state.lobby.playerList.filter(entry => entry.piece.dead).length === 1 && player.piece.dead;
}

function lastTwo(state: GameState, player: Player): boolean {
    return state.lobby.playerList.filter(entry => !entry.piece.dead).length === 2 && !player.piece.dead;
}

function totalDeadThree(state: GameState): boolean { return state.lobby.playerList.filter(entry => entry.piece.dead).length === 3; }
function shadowDeadButAlive(state: GameState): boolean {
    const shadows = state.lobby.playerList.filter(entry => entry.piece.character.category === CharacterCategory.shadow);
    return shadows.some(entry => entry.piece.dead) && shadows.some(entry => !entry.piece.dead);
}
function shadowsDead(state: GameState): boolean { return state.lobby.playerList.filter(entry => entry.piece.character.category === CharacterCategory.shadow).every(entry => entry.piece.dead); }
function huntersDead(state: GameState): boolean { return state.lobby.playerList.filter(entry => entry.piece.character.category === CharacterCategory.hunter).every(entry => entry.piece.dead); }
function threeNeutralsDead(state: GameState): boolean { return state.lobby.playerList.filter(entry => entry.piece.character.category === CharacterCategory.neutral && entry.piece.dead).length === 3; }

const specialVictoryItems = ['Talisman', 'Spear of Longinus', 'Holy Robe', 'Silver Rosary'];
function equipAllThree(_state: GameState, player: Player): boolean { return player.piece.items.filter(item => specialVictoryItems.includes(item.name)).length >= 3; }
function equipFive(_state: GameState, player: Player): boolean { return player.piece.items.filter(item => item.isItem).length === 5; }
function alive(_state: GameState, player: Player): boolean { return !player.piece.dead; }

function rightOrLeft(state: GameState, player: Player): boolean {
    const playersInTurnOrder = state.lobby.playerList;
    const playerIndex = playersInTurnOrder.findIndex(entry => entry.user.id === player.user.id);
    if (playerIndex === -1 || playersInTurnOrder.length < 2) return false;
    const direction = player.piece.abilityUsed ? -1 : 1;
    const adjacentPlayer = playersInTurnOrder[(playerIndex + direction + playersInTurnOrder.length) % playersInTurnOrder.length];
    return state.victors?.includes(adjacentPlayer.user.id) ?? false;
}

const victoryFunctions: Record<string, (state: GameState, player: Player, targets?: Piece[]) => boolean> = {
    killThirteen, onAltar, dieFirst, lastTwo, totalDeadThree, shadowDeadButAlive, shadowsDead, huntersDead, threeNeutralsDead, equipAllThree, equipFive, alive, rightOrLeft
};

export function CustomVictoryFunction(state: GameState, player: Player, targets?: Piece[]): boolean {
    return player.piece.character.victoryCondition?.some(condition => victoryFunctions[condition]?.(state, player, targets) ?? false) ?? false;
}
