
import {
  Route,
  Routes,
  HashRouter,
  Navigate
} from 'react-router';
import { lazy, Suspense, useEffect, type ReactNode } from 'react';
import './App.css';
import { useAppDispatch, useAppSelector } from './store/hooks';
import { ConnectionState } from './helpers/common';
import { clearExpiredGame } from './store/connection/connectionActions';
import { isGameExpired } from './helpers/gameExpiry';
import VersionMismatchDialog from './components/VersionMismatchDialog';
import * as Sentry from "@sentry/react";

Sentry.init({
  dsn: "https://54ba9827ce4719e69051d71d446d6d80@o4512207188393984.ingest.us.sentry.io/4512207199207424",
  integrations: [
    Sentry.browserTracingIntegration(),
    Sentry.replayIntegration()
  ],
  // Tracing
  tracesSampleRate: 1.0, //  Capture 100% of the transactions
  // Set 'tracePropagationTargets' to control for which URLs distributed tracing should be enabled
  tracePropagationTargets: ["localhost", /^https:\/\/kurtaclan\.github\.io\/shadow_hunters/],
  // Session Replay
  replaysSessionSampleRate: 0.1, // This sets the sample rate at 10%. You may want to change it to 100% while in development and then sample at a lower rate in production.
  replaysOnErrorSampleRate: 1.0 // If you're not already sampling the entire session, change the sample rate to 100% when sampling sessions where errors occur.
});

const Home = lazy(() => import('./components/Home'));
const GameRoom = lazy(() => import('./components/GameRoom'));
const GameBoard = lazy(() => import('./components/GameBoard'));

function GameExpiryGuard({ children }: { children: ReactNode }) {
  const dispatch = useAppDispatch();
  const connection = useAppSelector((state) => state.connection) as ConnectionState;
  const expired = isGameExpired(connection.gameState);

  useEffect(() => {
    if (expired) dispatch(clearExpiredGame());
  }, [dispatch, expired]);

  return expired ? <Navigate to='/' replace /> : children;
}

function App() {
  const connection = useAppSelector((state) => state.connection) as ConnectionState;

  return (
    <HashRouter>
      <GameExpiryGuard>
        <Suspense fallback={null}>
          <Routes>
            <Route index element={<Home />} />
            <Route path='Room' element={<GameRoom />} />
            <Route path='Game' element={<GameBoard />} />
          </Routes>
        </Suspense>
        {connection.versionMismatch ? <VersionMismatchDialog
          remoteVersion={connection.versionMismatch.remoteVersion}
          onRefresh={() => window.location.reload()} /> : undefined}
      </GameExpiryGuard>
    </HashRouter>
  );
}

export default App;
