import { Card, CardActionResult, Character, CharacterCategory, ChoiceType, Decks, GameState, ItemActionResult, LogEntry, Piece, Player, rollDice, Target } from './common';
export { CustomVictoryFunction } from './victoryConditions';

function hermit(state: GameState, card: Card, target?: string, assumedCategory?: CharacterCategory): CardActionResult {
    if (target === undefined) {
        return { logEntry: [], choice: { card: card, type: ChoiceType.target, target: state.currentPlayer } };
    }
    if (target === state.currentPlayer) {
        return { logEntry: [] };
    }

    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer)!;
    const targetPlayer = state.lobby.playerList.find(player => player.user.id === target)!;
    const targetCategory = assumedCategory ?? targetPlayer.piece.character.category;
    const withDamage = (damage: number): Player => ({
        ...targetPlayer,
        piece: { ...targetPlayer.piece, damage: Math.max(0, damage) }
    });
    const result = (player: Player, outcome: string, choice?: CardActionResult['choice']): CardActionResult => ({
        logEntry: [{
            source: 'Card',
            text: `gave Hermit Card to ${targetPlayer.user.userName} and ${outcome}.`,
            userName: currentPlayer.user.userName,
            info: `card_backs/green`
        }],
        playersTargeted: [player],
        choice
    });
    const damageOutcome = (damage: number) => {
        const difference = damage - targetPlayer.piece.damage;
        if (difference > 0) return `dealt ${difference} damage to ${targetPlayer.user.userName}`;
        if (difference < 0) return `healed ${Math.abs(difference)} damage from ${targetPlayer.user.userName}`;
        return `had no effect on ${targetPlayer.user.userName}`;
    };

    const hermitName = card.name.split(' ')[1] ?? 'error';
    if (targetPlayer.piece.character.name === 'Unknown' && assumedCategory === undefined) {
        return {
            logEntry: [{
                source: 'Card',
                text: `gave Hermit Card to ${targetPlayer.user.userName}.`,
                userName: currentPlayer.user.userName,
                info: 'card_backs/green'
            }],
            playersTargeted: [targetPlayer],
            choice: { type: ChoiceType.hermitFaction, card, target: targetPlayer.user.id }
        };
    }
    switch (hermitName) {
        case 'Aid': {
            const damage = targetCategory === CharacterCategory.hunter
                ? targetPlayer.piece.damage === 0 ? targetPlayer.piece.damage + 1 : targetPlayer.piece.damage - 1
                : targetPlayer.piece.damage;
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Anger': {
            const canGiveEquipment = targetCategory !== CharacterCategory.neutral;
            return result(targetPlayer,
                canGiveEquipment ? `${targetPlayer.user.userName} must give an item` : `had no effect on ${targetPlayer.user.userName}`,
                canGiveEquipment ? { type: ChoiceType.equipment, card, target: targetPlayer.user.id } : undefined);
        }
        case 'Blackmail': {
            const canGiveEquipment = targetCategory !== CharacterCategory.shadow;
            return result(targetPlayer,
                canGiveEquipment ? `${targetPlayer.user.userName} must give an item` : `had no effect on ${targetPlayer.user.userName}`,
                canGiveEquipment ? { type: ChoiceType.equipment, card, target: targetPlayer.user.id } : undefined);
        }
        case 'Bully': {
            const damage = targetPlayer.piece.damage + (targetPlayer.piece.character.maxHealth <= 11 ? 1 : 0);
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Exorcism': {
            const damage = targetPlayer.piece.damage + (targetCategory === CharacterCategory.shadow ? 2 : 0);
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Greed': {
            if (targetCategory === CharacterCategory.hunter) {
                return result(targetPlayer, `had no effect on ${targetPlayer.user.userName}`);
            }
            if (targetPlayer.piece.items.length === 0) {
                const damage = targetPlayer.piece.damage + 1;
                return result(withDamage(damage), damageOutcome(damage));
            }
            return result(targetPlayer, `${targetPlayer.user.userName} must choose to give an item or take 1 damage`, {
                type: ChoiceType.hermitGreed,
                card,
                target: targetPlayer.user.id
            });
        }
        case 'Huddle': {
            const damage = targetCategory === CharacterCategory.shadow
                ? targetPlayer.piece.damage === 0 ? targetPlayer.piece.damage + 1 : targetPlayer.piece.damage - 1
                : targetPlayer.piece.damage;
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Nurturance': {
            const damage = targetCategory === CharacterCategory.neutral
                ? targetPlayer.piece.damage === 0 ? targetPlayer.piece.damage + 1 : targetPlayer.piece.damage - 1
                : targetPlayer.piece.damage;
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Prediction': {
            const revealedCharacter: Card = { ...targetPlayer.piece.character, drawDeck: Decks.characters };
            return result(targetPlayer, `saw ${targetPlayer.user.userName}'s character`, {
                type: ChoiceType.showCard,
                card: revealedCharacter,
                target: state.currentPlayer,
                value: targetPlayer.user.id
            });
        }
        case 'Slap': {
            const damage = targetPlayer.piece.damage + (targetCategory === CharacterCategory.hunter ? 1 : 0);
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Spell': {
            const damage = targetPlayer.piece.damage + (targetCategory === CharacterCategory.shadow ? 1 : 0);
            return result(withDamage(damage), damageOutcome(damage));
        }
        case 'Tough': {
            const damage = targetPlayer.piece.damage + (targetPlayer.piece.character.maxHealth >= 12 ? 2 : 0);
            return result(withDamage(damage), damageOutcome(damage));
        }
        default:
            return result(targetPlayer, `had no effect on ${targetPlayer.user.userName}`);
    }
}

function banana(state: GameState, card: Card): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };
    const damage = playerTargeted.piece.items.length === 0 ? 1 : 0;
    playerTargeted.piece.damage += damage;
    const playerName = currentPlayer.user.userName;

    return {
        logEntry: damage === 1 ? [{
            text: `dealt 1 damage to themselves.`,
            source: 'Card',
            userName: playerName,
            info: `${card.drawDeck}/${card.name}`
        }] : [], playersTargeted: [playerTargeted], choice: damage === 1 ? undefined : { type: ChoiceType.equipment, card, target: playerTargeted.user.id }
    };
}

function diabolic(state: GameState, card: Card): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };

    return { logEntry: [], playersTargeted: [playerTargeted], choice: playerTargeted.piece.character.category === CharacterCategory.shadow ? { type: ChoiceType.reveal, card, target: playerTargeted.user.id } : undefined };
}

function dynamite(state: GameState, card: Card): CardActionResult | undefined {
    const result = rollDice([6, 4]);
    const playerName = state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0].user.userName;
    const playersTargeted = state.lobby.playerList.filter(x => !x.piece.dead && x.piece.position === result[0] + result[1]).map(x => { return { ...x, piece: { ...x.piece, damage: hasTalisman(x.piece) ? x.piece.damage : x.piece.damage + 3 } } });
    if (playersTargeted.length === 0) {
        return undefined;
    }

    return {
        playersTargeted, logEntry: [{
            text: `rolled a ${result}, and dealt 3 damage to ${playersTargeted.map(x => x.user.userName).join(', ')}.`,
            source: 'Card',
            userName: playerName,
            info: `${card.drawDeck}/${card.name}`
        }]
    };
}

function handgun(state: GameState, card: Card): ItemActionResult {
    const currentPlayer = state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0];
    return { targets: attackRangeFor(state, currentPlayer).map(player => player.user), card };
}

function spiritual(state: GameState, card: Card, target?: string): CardActionResult {
    if (target === undefined) {
        return { logEntry: [], choice: { card: card, type: ChoiceType.target, target: state.currentPlayer } };
    };

    const result = rollDice([6])[0];
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };

    if (result <= 4) {
        const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };
        playerTargeted.piece.damage += 3;

        return {
            playersTargeted: [playerTargeted],
            logEntry: [{
                text: `rolled a ${result}, and dealt 3 damage to themselves.`,
                source: 'Card',
                userName: currentPlayer.user.userName,
                info: `${card.drawDeck}/${card.name}`
            }]
        };
    }
    else {
        const targetPlayer = state.lobby.playerList.find(player => player.user.id === target);
        if (!targetPlayer || targetPlayer.piece.dead) return { logEntry: [] };
        const playerTargeted = { ...targetPlayer, piece: { ...targetPlayer.piece } };
        playerTargeted.piece.damage += 3;

        return {
            playersTargeted: [playerTargeted],
            logEntry: [{
                text: `rolled a ${result}, and dealt 3 damage to ${playerTargeted.user.userName}.`,
                source: 'Card',
                userName: currentPlayer.user.userName,
                info: `${card.drawDeck}/${card.name}`
            }]
        };
    }
}

function advent(state: GameState, card: Card): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };
    playerTargeted.piece.damage = playerTargeted.piece.revealed && playerTargeted.piece.character.category === CharacterCategory.hunter ? 0 : playerTargeted.piece.damage;

    return {
        logEntry: [],
        playersTargeted: [playerTargeted],
        choice: !playerTargeted.piece.revealed && playerTargeted.piece.character.category === CharacterCategory.hunter ? { card, type: ChoiceType.reveal, target: playerTargeted.user.id } : undefined
    };
}

function blessing(state: GameState, card: Card, target?: string): CardActionResult {
    if (target === undefined) {
        return { logEntry: [], choice: { card: card, type: ChoiceType.target, target: state.currentPlayer } };
    };

    const result = rollDice([6])[0];
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    const targetPlayer = state.lobby.playerList.find(player => player.user.id === target);
    if (!currentPlayer || !targetPlayer || targetPlayer.piece.dead) return { logEntry: [] };
    const playerName = currentPlayer.user.userName;
    const playerTargeted = { ...targetPlayer, piece: { ...targetPlayer.piece } };
    playerTargeted.piece.damage = Math.max(0, playerTargeted.piece.damage - result);

    return {
        playersTargeted: [playerTargeted],
        logEntry: [{
            text: `rolled a ${result} and healed ${result} damage from ${playerTargeted.user.userName === playerName ? 'themselves' : playerTargeted.user.userName}.`,
            source: 'Card',
            userName: playerName,
            info: `${card.drawDeck}/${card.name}`
        }]
    };
}

function chocolate(state: GameState, card: Card): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };
    const validTarget = validChocolateTarget(playerTargeted.piece.character);
    playerTargeted.piece.damage = playerTargeted.piece.revealed && validTarget ? 0 : playerTargeted.piece.damage;

    return {
        playersTargeted: [playerTargeted],
        choice: validTarget && !playerTargeted.piece.revealed ? { type: ChoiceType.reveal, card, target: playerTargeted.user.id } : undefined,
        logEntry: playerTargeted.piece.revealed && validTarget ?
            [{
                text: 'healed all damage from themselves.',
                source: 'Card',
                userName: playerTargeted.user.userName,
                info: `${card.drawDeck}/${card.name}`
            }] : []
    };
}

function validChocolateTarget(character: Character) {
    return (character.maxHealth === 8 && character.category === CharacterCategory.neutral) || (character.maxHealth === 10 && character.category === CharacterCategory.hunter)
        || (character.maxHealth === 11 && character.category === CharacterCategory.shadow);
}

function concealed(state: GameState): CardActionResult {
    return { logEntry: [], nextPlayer: state.currentPlayer };
}

function disenchant(state: GameState): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };

    if (playerTargeted.piece.character.category === CharacterCategory.shadow) {
        playerTargeted.piece.revealed = true;
        return { logEntry: [], playersTargeted: [playerTargeted] };
    }

    return { logEntry: [] };
}

function first(state: GameState, card: Card, target?: string): CardActionResult {
    if (target === undefined) {
        return { logEntry: [], choice: { card: card, type: ChoiceType.target, target: state.currentPlayer } };
    };

    const targetPlayer = state.lobby.playerList.find(player => player.user.id === target);
    if (!targetPlayer || targetPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...targetPlayer, piece: { ...targetPlayer.piece } };
    playerTargeted.piece.damage = 7;

    return { logEntry: [], playersTargeted: [playerTargeted] };
}

function guardian(state: GameState): CardActionResult {
    const currentPlayer = state.lobby.playerList.find(player => player.user.id === state.currentPlayer);
    if (!currentPlayer || currentPlayer.piece.dead) return { logEntry: [] };
    const playerTargeted = { ...currentPlayer, piece: { ...currentPlayer.piece } };
    playerTargeted.piece.protected = true;

    return { logEntry: [], playersTargeted: [playerTargeted] };
}

function spear(state: GameState, card: Card): ItemActionResult {
    const playerTargeted = { ...state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0] };

    return {
        modifier: playerTargeted.piece.revealed && playerTargeted.piece.character.category === CharacterCategory.hunter ? 2 : 0,
        choice: !playerTargeted.piece.revealed && playerTargeted.piece.character.category ? { type: ChoiceType.reveal, card, target: playerTargeted.user.id } : undefined,
        card
    };
}

function holy(_state: GameState, card: Card): ItemActionResult {
    return {
        modifier: -1,
        card
    };
}

function hasTalisman(piece: Piece) {
    return piece.items.filter(x => x.name === 'Talisman').length > 0;
}

function validTalisman(piece: Piece, card: Card) {
    return hasTalisman(piece) && talismanCard.includes(card.name);
}

export function hasSword(player: Player): boolean {
    return player.piece.items.filter(x => x.name === 'Cursed Sword Masamune').length > 0
}

export function hasMachineGun(player: Player): boolean {
    return player.piece.items.some(item => item.name === 'Machine Gun');
}

export function usesSingleDieAttack(player: Player): boolean {
    return hasSword(player) || player.piece.character.ability?.name === 'hornOfWarOutbreak';
}

export function attackRangeFor(state: GameState, player: Player): Player[] {
    const usingHandgun = player.piece.items.some(item => item.name === 'Handgun');
    const positions = usingHandgun
        ? player.piece.position <= 1
            ? [2, 3, 4, 5]
            : player.piece.position <= 3
                ? [0, 1, 4, 5]
                : [0, 1, 2, 3]
        : player.piece.position % 2 === 0
            ? [player.piece.position, player.piece.position + 1]
            : [player.piece.position, player.piece.position - 1];
    return state.lobby.playerList.filter(candidate => !candidate.piece.dead && candidate.piece.position !== -1
        && candidate.user.id !== player.user.id && positions.includes(candidate.piece.position));
}

export function attackModifierFor(player: Player): number {
    return player.piece.items.reduce((modifier, item) => modifier + (item.modifier ?? 0), 0)
        + (player.piece.items.some(item => item.name === 'Spear of Longinus')
            && player.piece.revealed && player.piece.character.category === CharacterCategory.hunter ? 2 : 0);
}

export function getCompass(player: Player): Card | undefined {
    const items = player.piece.items.filter(x => x.name === 'Mystic Compass');
    return items.length > 0 ? items[0] : undefined;
}

export function hasRobe(player: Player): boolean {
    return player.piece.items.filter(x => x.name === 'Holy Robe').length > 0
}

const talismanCard = ['BloodThirsty Spider', 'Vampire Bat 1', 'Vampire Bat 2', 'Vampire Bat 3'];

const cardFunction: { [K: string]: Function } = {
    hermit,
    banana,
    guardian,
    diabolic,
    dynamite,
    advent,
    spiritual,
    blessing,
    chocolate,
    concealed,
    first,
    disenchant
};

const itemFunction: { [K: string]: Function } = {
    holy,
    spear,
    handgun
};

export function CustomCardFunction(state: GameState, card: Card, target?: string, assumedHermitCategory?: CharacterCategory): CardActionResult | undefined {
    // Deck cards are named "Hermit's …", while the implementation is named
    // `hermit`. Normalize possessives before selecting the card handler.
    const functionName = card.name.toLowerCase().replace(/'s\b/, '').split(' ')[0] ?? '';
    let result: CardActionResult;
    if (cardFunction[functionName]) {
        result = cardFunction[functionName](state, card, target, assumedHermitCategory);
    }
    else {
        if (target === undefined && (card.damageTarget === Target.both || card.damageTarget === Target.player
            || card.healTarget === Target.player)) {
            return { logEntry: [], choice: { card: card, type: ChoiceType.target, target: state.currentPlayer } };
        }

        result = damageAndHealPlayers(state, card, target);
    }

    if (result === undefined) {
        return undefined;
    }

    return { ...result, logEntry: result.logEntry.map(entry => ({ ...entry, text: entry.text })) };
}

export function CustomItemFunction(state: GameState, card: Card, target?: string): ItemActionResult {
    const functionName = card.name.toLowerCase().split(' ')[0] ?? '';
    if (itemFunction[functionName]) {
        return itemFunction[functionName](state, card, target);
    }

    return {};
}

function damageAndHealPlayers(state: GameState, card: Card, target?: string): CardActionResult {
    let players: Player[] = [];
    let logs: LogEntry[] = [];
    const currentPlayerName = state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0].user.userName;

    if (card.damageTarget === Target.all) {
        return {
            playersTargeted: state.lobby.playerList.filter(player => !player.piece.dead).map(x => {
                return {
                    ...x, piece: {
                        ...x.piece,
                        damage: !validTalisman(x.piece, card) ? x.piece.damage + card.damage! : x.piece.damage
                    }
                }
            }),
            logEntry: [{
                source: 'Card',
                text: `dealt ${card.damage} to everyone.`,
                userName: currentPlayerName,
                info: `${card.drawDeck}/${card.name}`
            }]
        };
    }
    else if (card.damageTarget === Target.both) {
        players = [...state.lobby.playerList.filter(x => !x.piece.dead && (x.user.id === state.currentPlayer
            || x.user.id === target)).map(x => {
                return {
                    ...x, piece: {
                        ...x.piece,
                        damage: !validTalisman(x.piece, card) ? x.piece.damage + card.damage! : x.piece.damage
                    }
                }
            })];

        logs = players.map(x => {
            return {
                source: 'Card',
                text: validTalisman(x.piece, card) ? `Talisman protected ${x.user.userName}` : `dealt ${card.damage} to ${x.user.userName === currentPlayerName ? 'themselves' : x.user.userName}`,
                userName: currentPlayerName,
                info: `${card.drawDeck}/${card.name}`
            }
        });
    }
    else if (card.damageTarget === Target.player) {
        const targetPlayer = state.lobby.playerList.filter(x => x.user.id === target)[0];
        if (!targetPlayer || targetPlayer.piece.dead) return { logEntry: [] };
        players.push({
            ...targetPlayer,
            piece: {
                ...targetPlayer.piece,
                damage: !validTalisman(targetPlayer.piece, card) ? targetPlayer.piece.damage + card.damage! : targetPlayer.piece.damage
            }
        });
        logs.push({
            source: 'Card',
            text: validTalisman(targetPlayer.piece, card) ? `Talisman protected ${targetPlayer.user.userName}`
                : `dealt ${card.damage} to ${targetPlayer.user.userName === currentPlayerName ? 'themselves' : targetPlayer.user.userName}`,
            userName: currentPlayerName,
            info: `${card.drawDeck}/${card.name}`
        });
    }
    else if (card.damageTarget === Target.self) {
        const targetPlayer = state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0];
        players.push({
            ...targetPlayer,
            piece: {
                ...targetPlayer.piece,
                damage: !validTalisman(targetPlayer.piece, card) ? targetPlayer.piece.damage + card.damage! : targetPlayer.piece.damage
            }
        });

        logs.push({
            source: 'Card',
            text: validTalisman(targetPlayer.piece, card) ? `Talisman protected ${targetPlayer.user.userName}` : `dealt ${card.damage} to themselves`,
            userName: currentPlayerName,
            info: `${card.drawDeck}/${card.name}`
        });
    }

    if (card.healTarget === Target.all) {
        return {
            playersTargeted: state.lobby.playerList.filter(player => !player.piece.dead).map(x => {
                return {
                    ...x, piece: {
                        ...x.piece,
                        damage: Math.max(0, x.piece.damage - card.heal!)
                    }
                }
            }),
            logEntry: [{
                source: 'Card',
                text: `healed everyone for ${card.heal}.`,
                userName: currentPlayerName,
                info: `${card.drawDeck}/${card.name}`
            }]
        };
    }
    else if (card.healTarget === Target.both) {
        players = [...state.lobby.playerList.filter(x => !x.piece.dead && (x.user.id === state.currentPlayer
            || x.user.id === target)).map(x => {
                return {
                    ...x, piece: {
                        ...x.piece,
                        damage: Math.max(0, x.piece.damage - card.heal!)
                    }
                }
            })];

        logs = players.map(x => {
            return {
                source: 'Card',
                text: `healed ${x.user.userName === currentPlayerName ? 'themselves' : x.user.userName} for ${card.heal}`,
                userName: currentPlayerName,
                info: `${card.drawDeck}/${card.name}`
            }
        });
    }
    else if (card.healTarget === Target.player) {
        const targetPlayer = state.lobby.playerList.filter(x => x.user.id === target)[0];
        if (!targetPlayer || targetPlayer.piece.dead) return { logEntry: [] };
        players.push({
            ...targetPlayer,
            piece: {
                ...targetPlayer.piece,
                damage: Math.max(0, targetPlayer.piece.damage - card.heal!)
            }
        });
    }
    else if (card.healTarget === Target.self) {
        const targetPlayer = state.lobby.playerList.filter(x => x.user.id === state.currentPlayer)[0];
        players.push({
            ...targetPlayer,
            piece: {
                ...targetPlayer.piece,
                damage: Math.max(0, targetPlayer.piece.damage - card.heal!)
            }
        });
    }

    return {
        playersTargeted: players.length !== 0 ? players : undefined,
        logEntry: logs.length !== 0 ? logs : []
    };
}
