import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import Typography from '@mui/material/Typography';
import { APP_VERSION } from '../helpers/appVersion';

export default function VersionMismatchDialog({ remoteVersion, onRefresh }:
    { remoteVersion?: string, onRefresh: () => void }) {
    const remoteDescription = remoteVersion ? `Version ${remoteVersion}` : 'an older version that cannot report its version';

    return <Dialog open aria-labelledby='version-mismatch-title'>
        <DialogTitle id='version-mismatch-title'>Refresh Required</DialogTitle>
        <DialogContent>
            <Typography>Your game version is out of date or does not match another player’s version. Refresh the page to get the latest version before continuing.</Typography>
            <Typography sx={{ marginTop: 1 }} variant='body2'>Your version: {APP_VERSION}. Other player: {remoteDescription}.</Typography>
        </DialogContent>
        <DialogActions>
            <Button onClick={onRefresh} variant='contained' autoFocus>Refresh Page</Button>
        </DialogActions>
    </Dialog>;
}
