import { GameState } from './common';

export const GAME_MAX_AGE_MS = 4 * 60 * 60 * 1000;

export function createGameId(): string {
    if (typeof crypto !== 'undefined' && typeof crypto.randomUUID === 'function') return crypto.randomUUID();
    return `${Date.now()}-${Math.random().toString(36).slice(2)}`;
}

/** A persisted room/game is recoverable for four hours from its creation. */
export function isGameExpired(gameState: GameState, now = Date.now()): boolean {
    if (!gameState.hostId) return false;
    // Sessions persisted by older builds have no trustworthy creation time.
    // Treat them as expired rather than offering a potentially stale rejoin.
    if (typeof gameState.createdAt !== 'number' || !Number.isFinite(gameState.createdAt)) return true;
    return now - gameState.createdAt >= GAME_MAX_AGE_MS;
}
