import { ReactElement } from 'react';

export async function copyToClipboard(textToCopy: string) {
    // Navigator clipboard api needs a secure context (https)
    if (navigator.clipboard && window.isSecureContext) {
        await navigator.clipboard.writeText(textToCopy);
    } else {
        // Use the 'out of viewport hidden text area' trick
        const textArea = document.createElement('textarea');
        textArea.value = textToCopy;

        // Move textarea out of the viewport so it's not visible
        textArea.style.position = 'absolute';
        textArea.style.left = '-999999px';

        document.body.prepend(textArea);
        textArea.select();

        try {
            document.execCommand('copy');
        } catch (error) {
            console.error(error);
        } finally {
            textArea.remove();
        }
    }
}

export const copyRoomCode = (id: string, toastCallback: (message: string) => void) => {
    copyToClipboard(id)
        .then(() => {
            toastCallback('Copied Room Code to Clipboard');
        })
        .catch((e) => {
            console.log(e)
        });
}

export function RandomRange(min: number, max: number) {
    min = Math.ceil(min);
    max = Math.floor(max);

    return Math.floor(Math.random() * (max - min + 1)) + min;
}

export function _rollDice(sides: number) {
    return RandomRange(1, sides);
}

export function rollDice(dice: number[]) {
    return dice.map(x => _rollDice(x));
}

