import { ConnectionState, Decks, GameState, LogEntry, Player, PlayerAbility } from '../../helpers/common';
import { PeerConnection } from '../../helpers/peer';
import { CustomCharacterAbility } from '../../helpers/characterAbility';
import { resolveVictory } from './victoryResolver';

export const isHost = (state: ConnectionState) => state.gameState.hostId === state.peerId;

export function handleAbility(state: ConnectionState, event: PlayerAbility): ConnectionState {
    if (!isHost(state)) {
        PeerConnection.sendAbility(event, state.id!);
        return state;
    }
    if (state.gameState.pendingLoot) {
        return event.playerId === state.gameState.pendingLoot.killerId ? resolveLoot(state, event.itemName) : state;
    }
    if (state.gameState.pendingCounterattack) {
        return event.playerId === state.gameState.pendingCounterattack.responderId && event.skipCounterattack ? skipCounterattack(state) : state;
    }
    if (event.skipCounterattack) return state;

    const player = state.gameState.lobby.playerList.find(entry => entry.user.id === event.playerId);
    if (!player || state.gameState.gameEnded || event.playerId !== state.gameState.currentPlayer
        || player.piece.dead || player.piece.moved || player.piece.abilityUsed || player.piece.abilityBlocked || player.piece.character.ability?.automatic
        || !player.piece.character.ability) return state;

    const abilityResult = CustomCharacterAbility(state.gameState, event.playerId, event.targetId, event.roll, event.itemName);
    const playerList = applyAbility(state.gameState, event.playerId, event.targetId, event.roll, event.itemName, abilityResult);
    const victory = resolveVictory(state, playerList);
    return {
        ...state,
        gameState: {
            ...state.gameState,
            gameEnded: victory.gameEnded,
            winner: victory.winner,
            victors: victory.victors,
            lobby: {
                ...state.gameState.lobby,
                playerList,
                discard: abilityResult.discard ?? state.gameState.lobby.discard,
                gameLog: [...state.gameState.lobby.gameLog, abilityLog(player)]
            }
        }
    };
}

function resolveLoot(state: ConnectionState, itemName?: string): ConnectionState {
    const { killerId, items } = state.gameState.pendingLoot!;
    const selected = items.find(item => item.name === itemName);
    const discarded = selected ? items.filter(item => item !== selected) : items;
    const playerList = state.gameState.lobby.playerList.map(player => player.user.id === killerId && selected
        ? { ...player, piece: { ...player.piece, items: [...player.piece.items, selected] } }
        : player);
    return {
        ...state,
        gameState: {
            ...state.gameState,
            pendingLoot: undefined,
            lobby: {
                ...state.gameState.lobby,
                playerList,
                discard: {
                    ...state.gameState.lobby.discard,
                    green: { cards: [...discarded.filter(item => item.drawDeck === Decks.green), ...state.gameState.lobby.discard.green.cards] },
                    black: { cards: [...discarded.filter(item => item.drawDeck === Decks.black), ...state.gameState.lobby.discard.black.cards] },
                    white: { cards: [...discarded.filter(item => item.drawDeck === Decks.white), ...state.gameState.lobby.discard.white.cards] }
                },
                gameLog: [...state.gameState.lobby.gameLog, {
                    source: 'Loot',
                    text: selected ? `took ${selected.name}.` : 'The killer took no equipment.',
                    userName: playerList.find(player => player.user.id === killerId)!.user.userName,
                    info: selected ? `${selected.drawDeck}/${selected.name}` : 'No equipment taken'
                }]
            }
        }
    };
}

function skipCounterattack(state: ConnectionState): ConnectionState {
    const nextLivingPlayer = (startId: string, includeStart: boolean) => {
        const players = state.gameState.lobby.playerList;
        const start = Math.max(0, players.findIndex(player => player.user.id === startId));
        for (let offset = includeStart ? 0 : 1; offset < players.length + (includeStart ? 0 : 1); offset++) {
            const candidate = players[(start + offset) % players.length];
            if (!candidate.piece.dead) return candidate.user.id;
        }
        return startId;
    };
    const nextPlayer = nextLivingPlayer(state.gameState.nextPlayer, true);
    const followingPlayer = nextLivingPlayer(nextPlayer, false);
    return {
        ...state,
        gameState: {
            ...state.gameState,
            currentPlayer: nextPlayer,
            nextPlayer: followingPlayer,
            pendingCounterattack: undefined,
            lobby: {
                ...state.gameState.lobby,
                playerList: state.gameState.lobby.playerList.map(player => player.user.id === nextPlayer && !player.piece.dead
                    ? { ...player, piece: { ...player.piece, moved: false, attacked: false, protected: false } }
                    : player),
                gameLog: [...state.gameState.lobby.gameLog]
            }
        }
    };
}

export function applyAbility(gameState: GameState, ownerId: string, targetId?: string, roll?: number, itemName?: string, suppliedResult?: ReturnType<typeof CustomCharacterAbility>): Player[] {
    const owner = gameState.lobby.playerList.find(player => player.user.id === ownerId)!;
    const ability = owner.piece.character.ability!;
    const result = suppliedResult ?? CustomCharacterAbility(gameState, ownerId, targetId, roll, itemName);
    const revealOwner = ability.automatic && owner.piece.character.revealOnAutomaticAbility !== false;
    return result.players.map(player => player.user.id === ownerId ? {
        ...player,
        piece: { ...player.piece, abilityUsed: ability.passive ? player.piece.abilityUsed : true, revealed: revealOwner || player.piece.revealed }
    } : player);
}

export function abilityLog(player: Player): LogEntry {
    return { source: 'Ability', text: `${player.user.userName} used their ability.`, userName: player.user.userName, info: `characters/${player.piece.character.name}` };
}
