import Peer, { DataConnection, PeerErrorType, PeerError } from 'peerjs';
import { Data, DataType, PlayerAbility, PlayerAttack, PlayerChoice, PlayerEndTurn, PlayerEvent, PlayerMove, ConnectionState, PlayerDeath } from './common';
import { APP_VERSION } from './appVersion';

let peer: Peer | undefined;
let choiceCallback: (choice: PlayerChoice) => void;
let callBackSet = false;
const connectionMap: Map<string, DataConnection> = new Map<string, DataConnection>();
const remoteVersions: Map<string, string> = new Map<string, string>();

function versionedData(data: Data): Data {
    return { ...data, appVersion: APP_VERSION };
}

function versionMismatchData(remoteVersion?: string): Data {
    return {
        dataType: DataType.VersionMismatch,
        body: JSON.stringify({ expectedVersion: APP_VERSION, receivedVersion: remoteVersion })
    };
}

function sendData(connection: DataConnection, data: Data, allowVersionMismatch = false) {
    if (!allowVersionMismatch && remoteVersions.get(connection.peer) !== undefined
        && remoteVersions.get(connection.peer) !== APP_VERSION) {
        return false;
    }
    connection.send(versionedData(data));
    return true;
}

function mismatchExpectedVersion(data: Data): string | undefined {
    try {
        const payload = JSON.parse(data.body) as { expectedVersion?: unknown };
        return typeof payload.expectedVersion === 'string' ? payload.expectedVersion : undefined;
    } catch {
        return undefined;
    }
}

export const PeerConnection = {
    getPeer: () => peer,
    getCallbackSet: ()=> callBackSet,
    choiceCallback: (choice: PlayerChoice) => choiceCallback!(choice),

    setCallback: (choiceC: (choice: PlayerChoice) => void) => {
        callBackSet = true;
        choiceCallback = choiceC;
    },

    startPeerSession: (previousId?: string) => new Promise<string>((resolve, reject) => {
        try {
            if (peer) {
                resolve(peer.id);
                return;
            }

            if (previousId)
                peer = new Peer(previousId);
            else
                peer = new Peer();
            peer.on('open', (id) => {
                resolve(id);
            }).on('error', (e) => {
                console.log(e);
            })
        } catch (e) {
            console.log(e);
            reject(e);
        }
    }),

    closePeerSession: () => new Promise<void>((resolve, reject) => {
        try {
            if (peer) {
                peer.destroy();
                peer = undefined;
            }
            connectionMap.clear();
            remoteVersions.clear();
            resolve();
        } catch (e) {
            console.log(e);
            reject(e);
        }
    }),

    connectPeer: (id: string) => new Promise<void>((resolve, reject) => {
        if (!peer) {
            reject(new Error('Peer doesn\'t start yet'));
            return;
        }
        if (connectionMap.has(id)) {
            resolve();
            return;
        }
        try {
            const conn = peer.connect(id, { reliable: true });
            if (!conn) {
                reject(new Error('Connection can\'t be established'));
            } else {
                conn.on('open', function () {
                    connectionMap.set(id, conn);
                    peer?.removeListener('error', handlePeerError);
                    resolve();
                }).on('error', function (e) {
                    console.log(e);
                    peer?.removeListener('error', handlePeerError);
                    reject(e);
                });

                // When the connection fails due to expiry, the error gets emmitted
                // to the peer instead of to the connection.
                // We need to handle this here to be able to fulfill the Promise.
                const handlePeerError = (e: PeerError<`${PeerErrorType}`>) => {
                    if (e.type === 'peer-unavailable') {
                        const messageSplit = e.message.split(' ');
                        const peerId = messageSplit[messageSplit.length - 1];
                        if (id === peerId)
                            reject(e);
                    }
                }
                peer.on('error', handlePeerError);
            }
        } catch (e) {
            reject(e);
        }
    }),

    onIncomingConnection: (callback: (conn: DataConnection) => void) => {
        peer?.on('connection', function (conn) {
            connectionMap.set(conn.peer, conn);
            callback(conn);
        });
    },

    onConnectionDisconnected: (id: string, callback: () => void) => {
        if (!peer) {
            throw new Error('Peer doesn\'t start yet');
        }
        if (!connectionMap.has(id)) {
            throw new Error('Connection didn\'t exist');
        }
        const conn = connectionMap.get(id);
        if (conn) {
                conn.on('close', function () {
                    connectionMap.delete(id);
                    remoteVersions.delete(id);
                callback();
            });
        }
        callBackSet = false;
    },

    sendConnection: (id: string, data: Data): Promise<void> => new Promise((resolve, reject) => {
        if (!connectionMap.has(id)) {
            reject(new Error('Connection didn\'t exist'));
            return;
        }
        try {
            const conn = connectionMap.get(id);
            if (conn) {
                sendData(conn, data);
            }
        } catch (e) {
            reject(e);
        }
        resolve();
    }),

    onConnectionReceiveData: (id: string, callback: (f: Data) => void) => {
        if (!peer) {
            throw new Error('Peer doesn\'t start yet');
        }

        if (!connectionMap.has(id)) {
            throw new Error('Connection didn\'t exist');
        }

        const conn = connectionMap.get(id);
        if (conn) {
            conn.on('data', function (receivedData) {
                const data = receivedData as Data;
                if (!data || typeof data !== 'object' || typeof data.dataType !== 'string') return;
                // Version mismatch messages are intentionally accepted so the sender can
                // show an update prompt even though it is running another build.
                if (data.dataType === DataType.VersionMismatch) {
                    const expectedVersion = mismatchExpectedVersion(data);
                    if (expectedVersion) remoteVersions.set(id, expectedVersion);
                    callback(data);
                    return;
                }
                if (data.appVersion) remoteVersions.set(id, data.appVersion);
                if (data.appVersion !== APP_VERSION) {
                    const mismatch = versionMismatchData(data.appVersion);
                    sendData(conn, mismatch, true);
                    callback(mismatch);
                    return;
                }
                callback(data);
            })
        }
    },

    updateAllPlayers: async (state: ConnectionState) => {
        if (state.gameState.hostId === state.peerId) {
            await Promise.all([...connectionMap.values()].map((conn) =>
                sendData(conn, {
                    dataType: DataType.GameState,
                    body: JSON.stringify(state.gameState)
                })
            ));
        }
        else {
            console.log('You are not the host');
        }
    },

    sendAttack: async (attack: PlayerAttack, id: string) => {
        const conn = connectionMap.get(id)!;
        sendData(conn, {
                    dataType: DataType.PlayerAttack,
                    body: JSON.stringify(attack)
                });
    },

    sendMove: async (move: PlayerMove, id: string) => {
        const conn = connectionMap.get(id)!;
        sendData(conn, {
                    dataType: DataType.PlayerMove,
                    body: JSON.stringify(move)
                });
    },

    sendEndTurn: async (event: PlayerEndTurn, id: string) => {
        const conn = connectionMap.get(id)!;
        sendData(conn, { dataType: DataType.PlayerEndTurn, body: JSON.stringify(event) });
    },

    sendPlayerEvent: async (event: PlayerEvent) => {
        await Promise.all([...connectionMap.values()].map(conn =>
            sendData(conn, { dataType: DataType.PlayerEvent, body: JSON.stringify(event) })
        ));
    },

    sendDeath: async (death: PlayerDeath) => {
         await Promise.all([...connectionMap.values()].map((conn) =>
                sendData(conn, {
                    dataType: DataType.PlayerDeath,
                    body: JSON.stringify(death)
                })
            ));
    },

    sendAbility: async (ability: PlayerAbility, id: string) => {
        const conn = connectionMap.get(id)!;
        sendData(conn, {
            dataType: DataType.PlayerAbility,
            body: JSON.stringify(ability)
        });
    },

    sendChoice: async (choice: PlayerChoice, id: string) => {
        const conn = connectionMap.get(id)!;
        sendData(conn, {
                    dataType: DataType.PlayerChoice,
                    body: JSON.stringify(choice)
                });
    },
}
