import { CharacterCategory, ConnectionState, GameState, Piece, Player } from '../../helpers/common';
import { CustomVictoryFunction } from '../../helpers/cardAction';

export function resolveVictory(state: ConnectionState, playerList: Player[], targets?: Piece[]) {
    const gameState = { ...state.gameState, lobby: { ...state.gameState.lobby, playerList } };
    const huntersRemain = playerList.some(player => !player.piece.dead && player.piece.character.category === CharacterCategory.hunter);
    const shadowsRemain = playerList.some(player => !player.piece.dead && player.piece.character.category === CharacterCategory.shadow);
    const factionWinner = huntersRemain ? (shadowsRemain ? undefined : CharacterCategory.hunter) : (shadowsRemain ? CharacterCategory.shadow : undefined);
    const factionVictors = factionWinner === undefined
        ? []
        : playerList.filter(player => !player.piece.dead && player.piece.character.category === factionWinner).map(player => player.user.id);
    const neutralVictoryState = { ...gameState, victors: factionVictors };
    const neutralVictors = playerList.filter(player => hasMetNeutralVictoryCondition(neutralVictoryState, player, targets));
    const earlyNeutralVictory = neutralVictors.some(player => player.piece.character.endGameOnVictory);
    const gameEnded = earlyNeutralVictory || factionWinner !== undefined;

    if (!gameEnded) return { gameEnded: false, winner: undefined, victors: undefined };

    return {
        gameEnded: true,
        winner: factionWinner ?? CharacterCategory.neutral,
        victors: [...factionVictors, ...neutralVictors.map(player => player.user.id)]
    };
}

function hasMetNeutralVictoryCondition(gameState: GameState, player: Player, targets?: Piece[]): boolean {
    return player.piece.character.category === CharacterCategory.neutral
        && !!player.piece.character.victoryCondition
        && CustomVictoryFunction(gameState, player, targets);
}
