import { configureStore } from '@reduxjs/toolkit'
import { PeerReducer } from './peer/peerReducer';
import { ConnectionReducer } from './connection/connectionReducer';
import { persistStore, persistReducer } from 'redux-persist'
import storage from 'redux-persist/lib/storage'
import { combineReducers } from 'redux';
import { getPersistConfig } from 'redux-deep-persist';
import expireInTransform from 'redux-persist-transform-expire-in';
import { gameStateReplicationMiddleware } from './connection/gameStateReplication';

const rootReducer = combineReducers({
    peer: PeerReducer,
    connection: ConnectionReducer
});

const expireIn = 24 * 60 * 60 * 1000;
const expirationKey = 'connection';

const persistConfig = getPersistConfig({
    key: 'root',
    storage,
    whitelist: ['peer.id', 'peer.userData.color', 'peer.userData.userName', 'connection'],
    transforms: [expireInTransform(expireIn, expirationKey, rootReducer),],
    rootReducer
});

export const store = configureStore({
    reducer: persistReducer(persistConfig, rootReducer),
    middleware: (getDefaultMiddleware) =>
        getDefaultMiddleware({
            serializableCheck: false,
        }).concat(gameStateReplicationMiddleware),
});

export const persistor = persistStore(store);

window.store = store;

// Infer the `RootState` and `AppDispatch` types from the store itself
export type RootState = ReturnType<typeof store.getState>;
// Inferred type: {posts: PostsState, comments: CommentsState, users: UsersState}
export type AppDispatch = typeof store.dispatch;
export const MinimumPlayers = 4;
export const isTestMode = import.meta.env.MODE === 'test' || import.meta.env.VITE_TEST_MODE === 'true';

