import { Card, DiscardBox, GameState, Player, Target } from './common';

export interface CharacterAbilityResult {
    players: Player[];
    extraTurn?: number;
    extraAttack?: boolean;
    discard?: DiscardBox;
}

const withPlayer = (players: Player[], playerId: string, update: (player: Player) => Player) =>
    players.map(player => player.user.id === playerId ? update(player) : player);

const updateDamage = (players: Player[], playerId: string, update: (damage: number) => number) =>
    withPlayer(players, playerId, player => ({ ...player, piece: { ...player.piece, damage: Math.max(0, update(player.piece.damage)) } }));

const updateRevealed = (players: Player[], playerId: string, update: (revealed: boolean) => boolean) =>
    withPlayer(players, playerId, player => ({ ...player, piece: { ...player.piece, revealed: update(player.piece.revealed) } }));

const stealItems = (players: Player[], playerId: string, update: (items: Card[]) => Card[]) =>
    withPlayer(players, playerId, player => ({ ...player, piece: { ...player.piece, items: update(player.piece.items) } }));

export function capriccio(players: Player[]): CharacterAbilityResult { return { players }; }
export function mothersLove(players: Player[], ownerId: string): CharacterAbilityResult { return { players: updateDamage(players, ownerId, () => 0) }; }
export function robbery(players: Player[], ownerId: string, targetId?: string, roll = 0, itemName?: string): CharacterAbilityResult {
    const target = players.find(player => player.user.id === targetId);
    if (!target) return { players };
    const stolenItems = players.length < 7 && roll >= 2
        ? target.piece.items.filter(item => item.name === itemName).slice(0, 1)
        : target.piece.dead ? target.piece.items : [];
    if (stolenItems.length === 0) return { players };
    const withoutItems = stealItems(players, target.user.id, items => items.filter(item => !stolenItems.includes(item)));
    return { players: stealItems(withoutItems, ownerId, items => [...items, ...stolenItems]) };
}
export function myGod(players: Player[], ownerId: string, targetId?: string): CharacterAbilityResult {
    const target = players.filter(x => x.user.id === targetId)[0];
    if (target.piece.dead && target.piece.character.maxHealth <= 12) {
        return { players: updateRevealed(players, ownerId, () => true) };
    }

    return { players };
}
export function stigmata(players: Player[], ownerId: string): CharacterAbilityResult { return { players: updateDamage(players, ownerId, damage => damage - 1) }; }
export function scream(players: Player[], ownerId: string): CharacterAbilityResult {
    if (players.some(p => p.piece.dead)) {
        return { players: updateRevealed(players, ownerId, () => true) };
    }

    return { players };
}
export function graveDigger(state: GameState, ownerId: string, itemName?: string): CharacterAbilityResult {
    const deckName = Object.keys(state.lobby.discard).find(deck => state.lobby.discard[deck].cards.some(card => card.name === itemName));
    if (!deckName || !itemName) return { players: state.lobby.playerList };
    const card = state.lobby.discard[deckName].cards.find(entry => entry.name === itemName)!;
    return {
        players: stealItems(state.lobby.playerList, ownerId, items => [...items, card]),
        discard: { ...state.lobby.discard, [deckName]: { cards: state.lobby.discard[deckName].cards.filter(entry => entry !== card) } }
    };
}
export function chainOfForbiddenCurse(players: Player[], _ownerId: string, targetId?: string): CharacterAbilityResult {
    return { players: targetId ? withPlayer(players, targetId, player => ({ ...player, piece: { ...player.piece, abilityBlocked: true } })) : players };
}
export function lightning(players: Player[], _ownerId: string, targetId?: string, roll = 0): CharacterAbilityResult { return { players: targetId ? updateDamage(players, targetId, damage => damage + roll) : players }; }
export function dynamiteNurse(players: Player[], _ownerId: string, targetId?: string): CharacterAbilityResult {
    return {
        players: targetId
            ? withPlayer(players, targetId, player => ({
                ...player,
                piece: { ...player.piece, damage: 7 }
            }))
            : players
    };
}
export function demolish(players: Player[], _ownerId: string, targetId?: string, roll = 0): CharacterAbilityResult { return { players: targetId ? updateDamage(players, targetId, damage => damage + roll) : players }; }
export function ghostlyBarrier(players: Player[], ownerId: string): CharacterAbilityResult { return { players: withPlayer(players, ownerId, player => ({ ...player, piece: { ...player.piece, protected: true } })) }; }
export function murderRay(players: Player[], _ownerId: string, targetId?: string): CharacterAbilityResult { return { players: targetId ? updateDamage(players, targetId, damage => damage + 3) : players }; }
export function deceit(players: Player[]): CharacterAbilityResult {
    return { players };
}
export function hornOfWarOutbreak(players: Player[]): CharacterAbilityResult {
    return { players };
}
export function suckBlood(players: Player[], ownerId: string): CharacterAbilityResult { return { players: updateDamage(players, ownerId, damage => damage - 2) }; }
export function counterAttack(players: Player[]): CharacterAbilityResult { return { players }; }
export function bloodyFeast(players: Player[], ownerId: string): CharacterAbilityResult { return { players: updateDamage(players, ownerId, damage => damage + 2), extraAttack: true }; }
export function multiplication(players: Player[]): CharacterAbilityResult { return { players, extraTurn: players.filter(player => player.piece.dead).length }; }

const abilityFunctions: Record<string, (players: Player[], ownerId: string, targetId?: string, roll?: number, itemName?: string) => CharacterAbilityResult> = {
    capriccio, mothersLove, robbery, myGod, stigmata, scream, chainOfForbiddenCurse, lightning, dynamiteNurse, demolish, ghostlyBarrier, murderRay, deceit, hornOfWarOutbreak, suckBlood, counterAttack, bloodyFeast, multiplication
};

export function CustomCharacterAbility(state: GameState, ownerId: string, targetId?: string, roll?: number, itemName?: string): CharacterAbilityResult {
    const owner = state.lobby.playerList.find(player => player.user.id === ownerId);
    const ability = owner?.piece.character.ability;
    if (!owner || !ability) return { players: state.lobby.playerList };
    if (ability.name === 'graveDigger') return graveDigger(state, ownerId, itemName);
    const handler = abilityFunctions[ability.name];
    const usesSelectedTarget = new Set([
        'chainOfForbiddenCurse', 'lightning', 'dynamiteNurse', 'demolish',
        'murderRay', 'myGod', 'robbery'
    ]).has(ability.name);
    const resolvedTarget = usesSelectedTarget || ability.target === Target.player || ability.target === Target.attacker
        ? targetId
        : ownerId;
    if (handler) return handler(state.lobby.playerList, ownerId, resolvedTarget, roll, itemName);
    return {
        players: resolvedTarget
            ? updateDamage(state.lobby.playerList, resolvedTarget, damage => damage + (ability.damage ?? 0) - (ability.heal ?? 0))
            : state.lobby.playerList
    };
}
