import RawDecks from './decks.json';

type ImageCard = { name: string };

const gameCardPaths = (deck: ImageCard[], deckName: string) =>
    deck.map(card => `assets/game/${deckName}/${card.name}.jpg`);

const characterPaths = Object.values(RawDecks.characters)
    .flatMap(characters => gameCardPaths(characters as ImageCard[], 'characters'));

export const publicImagePaths = [
    'sh_logo.jpg',
    'sh_text_logo.png',
    'assets/game/Board.jpg',
    'assets/game/card_backs/areas.jpg',
    'assets/game/card_backs/black.jpg',
    'assets/game/card_backs/characters.jpg',
    'assets/game/card_backs/green.jpg',
    'assets/game/card_backs/white.jpg',
    ...gameCardPaths(RawDecks.areas as ImageCard[], 'areas'),
    ...gameCardPaths(RawDecks.green as ImageCard[], 'green'),
    ...gameCardPaths(RawDecks.black as ImageCard[], 'black'),
    ...gameCardPaths(RawDecks.white as ImageCard[], 'white'),
    ...characterPaths
];

const cacheName = 'shadow-hunters-public-images-v1';
let preloadScheduled = false;

const publicImageUrls = () => {
    const base = new URL(import.meta.env.BASE_URL, window.location.origin);
    return publicImagePaths.map(path => new URL(path, base).toString());
};

const preloadWithImages = async (urls: string[]) => {
    await Promise.all(urls.map(url => new Promise<void>(resolve => {
        const image = new Image();
        image.onload = () => resolve();
        image.onerror = () => resolve();
        image.src = url;
    })));
};

const cacheImages = async () => {
    const urls = publicImageUrls();
    if (!('caches' in window)) {
        await preloadWithImages(urls);
        return;
    }
    try {
        const cache = await window.caches.open(cacheName);
        let nextUrl = 0;
        const worker = async () => {
            while (nextUrl < urls.length) {
                const url = urls[nextUrl++]!;
                if (await cache.match(url)) continue;
                try {
                    const response = await fetch(url, { cache: 'force-cache' });
                    if (response.ok) await cache.put(url, response);
                } catch {
                }
            }
        };
        await Promise.all(Array.from({ length: 6 }, worker));
    } catch {
        await preloadWithImages(urls);
    }
};

export function cachePublicImagesInBackground() {
    if (preloadScheduled || typeof window === 'undefined') return;
    preloadScheduled = true;
    const preload = () => { void cacheImages(); };
    const idleWindow = window as Window & {
        requestIdleCallback?: (callback: () => void, options?: { timeout: number }) => number
    };
    if (idleWindow.requestIdleCallback) {
        idleWindow.requestIdleCallback(preload, { timeout: 2_000 });
    } else {
        window.setTimeout(preload, 0);
    }
}
