import { StrictMode } from 'react'
import { createRoot } from 'react-dom/client'
import App from './App.tsx'
import './index.css'
import { persistor, store } from './store';
import { Provider } from 'react-redux';
import { PersistGate } from 'redux-persist/integration/react';
import { createTheme, ThemeProvider } from '@mui/material/styles';
import { themeOptions } from './helpers/theme.ts';
import { Box } from '@mui/system';
import Typography from '@mui/material/Typography';
import LinearProgress from '@mui/material/LinearProgress';
import { cachePublicImagesInBackground } from './helpers/publicImageCache.ts';

const innerTheme = createTheme(themeOptions);

createRoot(document.getElementById('root')!).render(
  <StrictMode>
    <Provider store={store}>
      <PersistGate loading={<Box role="status"><Typography variant="h3">Loading Shadow Hunters…</Typography><LinearProgress sx={{ width: '100%', height: '5px', marginTop: 2 }} aria-label="Loading…" /></Box>} persistor={persistor}>
        <ThemeProvider theme={innerTheme}>
          <App />
        </ThemeProvider>
      </PersistGate>
    </Provider>
  </StrictMode>,
)

cachePublicImagesInBackground();
